const INSTALLED_LIBRARY_HTML='<div class="install-command-hero"><b>📚 استعلام زندهٔ کتابخانه‌های نصب‌شده/قابل اجرا</b><br>این بخش از API خود محیط سؤال می‌کند و سپس نتیجهٔ واقعی همان محیط را نمایش می‌دهد.</div><div id="runtimeInstalledLibraries" class="install-command-grid"><article class="install-command-card"><h4>در حال استعلام…</h4><pre>لطفاً چند لحظه صبر کنید.</pre></article></div><div class="install-command-hero"><b>📚 کاتالوگ مرجع براساس محیط</b><br>هر محیط فقط کتابخانه‌ها و runtimeهایی را نشان می‌دهد که همان‌جا واقعاً نصب/قابل اجرا هستند؛ بنابراین Playwright/Puppeteer زیر Cloudflare Worker نمایش داده نمی‌شوند.</div>'+INSTALLED_LIBRARY_GROUPS_BY_ENV.map(env=>'<div class="install-command-hero"><b>'+esc(env.env)+'</b><br>'+esc(env.note)+'</div><div class="install-command-grid">'+env.groups.map(g=>'<article class="install-command-card"><h4>'+esc(g.label)+' <span class="chip">'+esc(g.type)+'</span></h4><pre>'+esc(g.items.join('\n'))+'</pre></article>').join('')+'</div>').join('');
const INSTALL_COMMAND_GROUPS=[{"key": "update", "title": "Update existing clone / Worker", "badge": "Code update", "body": "cd \"$HOME/new\"\ngit config --local --unset-all credential.helper || true\ngit config --local --replace-all credential.helper '!gh auth git-credential'\ngh auth setup-git || true\ngit fetch origin arena/01a0803e-new\ngit reset --hard origin/arena/01a0803e-new\ncd \"$HOME/new/cloudflare-scraper4\"\nnpm install --no-audit --prefer-online\nnpm run browsers:install || true\nnpm run version:check\ngrep version package.json | head -1\n# Expected: 1.131.0\n# Cloudflare Dashboard: Workers & Pages → Deployments → Redeploy latest commit"}, {"key": "desktop", "title": "VS Code / Desktop", "badge": "Node + Deployer", "body": "git clone --branch arena/01a0803e-new https://github.com/fazilatma/new.git\ncd new\nnpm install\ncd cloudflare-scraper4\nnpm install\nnode scripts/esbuild-check.mjs\nnpm run version:check\n# Expected: 1.131.0\nnpm run deployer:ui\n# Open the printed http://localhost:8790/?token=... URL\n# Browser engines for JavaScript-only shops. Without this step the\n# playwright/puppeteer engines cannot launch and are skipped.\nnpm run browsers:install"}, {"key": "windows-powershell", "title": "Windows PowerShell", "badge": "Choose install folder", "body": "# Choose the install directory yourself. Example: D:\\Scraper4 or E:\\Apps\\Scraper4\n$InstallRoot = Read-Host \"Install folder for Scraper4 (not forced to C:)\"\nif ([string]::IsNullOrWhiteSpace($InstallRoot)) { throw \"Install folder is required\" }\nNew-Item -ItemType Directory -Force -Path $InstallRoot | Out-Null\nSet-Location $InstallRoot\n# Install prerequisites if winget is available. You can also install Node.js LTS, Git, and GitHub CLI manually.\nif (Get-Command winget -ErrorAction SilentlyContinue) {\n  winget install --id Git.Git -e --source winget\n  winget install --id GitHub.cli -e --source winget\n  winget install --id OpenJS.NodeJS.LTS -e --source winget\n}\n# Restart PowerShell after first installing Node/Git if commands are not found.\nif (-not (Test-Path \"$InstallRoot\\new\\.git\")) {\n  git clone --branch arena/01a0803e-new https://github.com/fazilatma/new.git \"$InstallRoot\\new\"\n} else {\n  Set-Location \"$InstallRoot\\new\"\n  git fetch origin arena/01a0803e-new\n  git reset --hard origin/arena/01a0803e-new\n}\nSet-Location \"$InstallRoot\\new\\cloudflare-scraper4\"\nnpm install --no-audit --prefer-online\nnpm run browsers:install\nnode scripts/esbuild-check.mjs\nnpm run version:check\n# Expected: 1.131.0\n@\"\nDATABASE_URL=sqlite:data/scraper4.sqlite\nRUN_WORKER_IN_WEB=true\nLOCAL_SCRAPER_AUTO_UPDATE=true\nPORT=3000\n\"@ | Set-Content -Encoding UTF8 .env.local\n# Windows uses Node built-in SQLite - no PostgreSQL install/service needed.\n# Remove DATABASE_URL only if you prefer a remote/managed PostgreSQL URL.\nnpm run deployer:ui\n# Open the printed http://localhost:8790/?token=... URL. The app files stay under $InstallRoot\\new, not the default C: path."}, {"key": "windows-cmd", "title": "Windows Command Prompt", "badge": "Choose install folder", "body": "REM Choose the install directory yourself. Example: D:\\Scraper4 or E:\\Apps\\Scraper4\nset /p INSTALL_ROOT=Install folder for Scraper4 (not forced to C:): \nif \"%INSTALL_ROOT%\"==\"\" echo Install folder is required && exit /b 1\nmkdir \"%INSTALL_ROOT%\" 2>nul\ncd /d \"%INSTALL_ROOT%\"\nREM Install Node.js LTS, Git, and GitHub CLI manually, or use winget before running this block.\nwhere git || winget install --id Git.Git -e --source winget\nwhere node || winget install --id OpenJS.NodeJS.LTS -e --source winget\nwhere gh || winget install --id GitHub.cli -e --source winget\nif not exist \"%INSTALL_ROOT%\\new\\.git\" (\n  git clone --branch arena/01a0803e-new https://github.com/fazilatma/new.git \"%INSTALL_ROOT%\\new\"\n) else (\n  cd /d \"%INSTALL_ROOT%\\new\"\n  git fetch origin arena/01a0803e-new\n  git reset --hard origin/arena/01a0803e-new\n)\ncd /d \"%INSTALL_ROOT%\\new\\cloudflare-scraper4\"\nnpm install --no-audit --prefer-online\nnpm run browsers:install\nnode scripts\\esbuild-check.mjs\nnpm run version:check\nREM Expected: 1.131.0\n(\n  echo DATABASE_URL=sqlite:data/scraper4.sqlite\n  echo RUN_WORKER_IN_WEB=true\n  echo LOCAL_SCRAPER_AUTO_UPDATE=true\n  echo PORT=3000\n) > .env.local\nREM Windows uses Node built-in SQLite - no PostgreSQL install/service needed.\nREM Remove DATABASE_URL only if you prefer a remote/managed PostgreSQL URL.\nnpm run deployer:ui\nREM Open the printed http://localhost:8790/?token=... URL. The app files stay under %INSTALL_ROOT%\\new, not the default C: path."}, {"key": "termux", "title": "Termux / Android", "badge": "Phone local runtime", "body": "cd \"$HOME\"\npkg update -y\npkg upgrade -y\npkg install -y git gh openssh nodejs-lts python make clang chromium esbuild\nrm -rf \"$HOME/new\"\ngit config --global --unset-all credential.helper || true\ngh auth login --web -h github.com -p https\ngh auth setup-git\ngh repo clone fazilatma/new \"$HOME/new\" -- --branch arena/01a0803e-new --depth 1\ncd \"$HOME/new\"\ngit config --local --unset-all credential.helper || true\ngit config --local --replace-all credential.helper '!gh auth git-credential'\ngit config --local --get-all credential.helper\n# Correct output: !gh auth git-credential\n# Do NOT set: gh auth setup-git auth git-credential\ncd \"$HOME/new/cloudflare-scraper4\"\nnpm config set fetch-retries 5\nnpm config set fetch-retry-mintimeout 20000\nnpm config set fetch-retry-maxtimeout 90000\nnpm install --no-audit --prefer-online\nnpm run browsers:install || true\nCHROME_BIN=\"$(command -v chromium-browser || command -v chromium || true)\"\nnode scripts/esbuild-check.mjs\nnpm run version:check\n# Expected: 1.131.0\nif [ -n \"$CHROME_BIN\" ]; then printf \"BROWSER_EXECUTABLE_PATH=$CHROME_BIN\nPLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH=$CHROME_BIN\nPUPPETEER_EXECUTABLE_PATH=$CHROME_BIN\nLOCAL_SCRAPER_AUTO_UPDATE=true\n\" >> .env.local; fi\n# First \"Open scraper\" click runs render:build; on Termux/ARM that takes tens of seconds.\n# The deployer now waits for it. Raise the budget on a very slow device:\n#   export LOCAL_SCRAPER_PROXY_WAIT_MS=300000\n# If a build ever fails with \"cannot find esbuild\": Termux reports itself as\n# Android, where the native npm binary is often unavailable. v1.83.0 recovers\n# automatically using the system esbuild (pkg install esbuild) or the\n# WebAssembly build. To check it by hand:\n#   node scripts/esbuild-check.mjs\n# v1.90.0 fixes three Termux-only problems:\n#  1) After the deployer auto-updates to a new version it now restarts the\n#     scraper too (its start command runs render:build), so both the deployer\n#     and the scraper are rebuilt and you only refresh the scraper page.\n#  2) AI model tests used to sit on the queued-on-server message forever: the Node\n#     runtime had no background run, so progress was never reported. It now\n#     reports per-model progress and supports stop/resume, like the Worker.\n#  3) A profile that extracted fine on Cloudflare returned nothing here,\n#     because auto mode skipped the htmlrewriter engine and fell through to\n#     browsers that Android cannot run. Engine order now matches the Worker.\n# v1.91.0 fixes the diagnostic buttons returning 404 here. They were only ever\n#   implemented on the Cloudflare Worker, so on Termux every one of them said\n#   not found even though the visual selector preview loaded the same site.\n#   Extraction diagnostic, full debug, selector suggestion, import history,\n#   job/run priority, agent tools and the Workers AI catalog now all work here.\n#   The extraction diagnostic runs the real scrape pipeline and names the\n#   engine that won, so its report matches what a real run does.\n# If the deployer says \"Auto-update skipped: 1 uncommitted change(s)\" and the\n# version never moves, the stale lockfile is the cause. Force one update:\n#   cd \"$HOME/new\" && git checkout -- cloudflare-scraper4/package-lock.json\n#   git pull --ff-only origin arena/01a0803e-new\n# v1.93.0 fixes the database error on this device. Termux used to be forced\n#   onto PostgreSQL, so every refresh of the scraper page flashed\n#   connect ECONNREFUSED 127.0.0.1:5432 and the status light stayed red,\n#   because a stock phone has no PostgreSQL server installed. Termux now\n#   uses the built-in Node SQLite database (data/scraper4.sqlite) by\n#   default - no server, no daemon, nothing to start.\n#   An existing broken .env.local self-heals: a local PostgreSQL that\n#   refuses the connection now falls back to SQLite automatically\n#   instead of leaving the status light red forever.\n#   PostgreSQL stays fully supported - see the next card if you want it.\n# v1.101.0 installs the official Basalam SDK. Basalam only publishes it for\n# Python (there is no npm package), so sending now tries the real SDK first\n# through a python3 bridge and falls back to the REST API automatically.\npip install --upgrade basalam-sdk || pip install basalam-sdk || true\npython3 -c \"import basalam_sdk, sys; print('basalam-sdk OK')\" || echo \"basalam-sdk not installed - sending will use the REST API only\"\nnpm run deployer:ui\n"}, {"key": "termux-db", "title": "Termux PostgreSQL (optional)", "badge": "Only if you want Postgres", "body": "cd \"$HOME/new/cloudflare-scraper4\"\npkg install -y postgresql\nmkdir -p \"$PREFIX/var/lib/postgresql\"\n[ -f \"$PREFIX/var/lib/postgresql/PG_VERSION\" ] || initdb \"$PREFIX/var/lib/postgresql\"\npg_ctl -D \"$PREFIX/var/lib/postgresql\" -l \"$HOME/scraper4-postgres.log\" start || true\ncreatedb scraper4 || true\nprintf \"DATABASE_URL=postgresql://$(whoami)@localhost:5432/scraper4\\nRUN_WORKER_IN_WEB=true\\n\" > .env.local\ncat .env.local\n# Do not use postgres:postgres on Termux unless you created that role manually.\nnpm run version:check\n# Expected: 1.131.0\n# This card is OPTIONAL. Termux works out of the box on the built-in Node\n# SQLite database; follow it only if you specifically want PostgreSQL.\n# Switch back to SQLite at any time by putting this line in .env.local:\n#   DATABASE_URL=sqlite:data/scraper4.sqlite\n# PostgreSQL must be started again after every Termux restart, otherwise you\n# get connect ECONNREFUSED 127.0.0.1:5432. Since v1.93.0 the app then falls\n# back to SQLite instead of staying unusable. Start it with:\n#   pg_ctl -D $PREFIX/var/lib/postgresql start\n# Windows users: skip this card. On Windows the deployer uses the built-in Node SQLite database\n# (DATABASE_URL=sqlite:data/scraper4.sqlite) and needs no PostgreSQL service."}, {"key": "docker-db", "title": "Desktop/Codespaces PostgreSQL", "badge": "Docker DB", "body": "cd new/cloudflare-scraper4\ndocker rm -f scraper4-postgres || true\ndocker run --name scraper4-postgres -e POSTGRES_PASSWORD=postgres -e POSTGRES_DB=scraper4 -p 5432:5432 -d postgres:16\nprintf 'DATABASE_URL=postgresql://postgres:postgres@localhost:5432/scraper4\\nRUN_WORKER_IN_WEB=true\\n' > .env.local\nnpm run version:check\n# Expected: 1.131.0\n# No Docker available? Leave DATABASE_URL empty or set sqlite:data/scraper4.sqlite\n# and the deployer falls back to the built-in Node SQLite database."}, {"key": "render", "title": "Render.com", "badge": "Panel setup", "body": "1) Render Dashboard → New → PostgreSQL\n2) Copy Internal Database URL\n3) Web Service → Environment:\n   DATABASE_URL = Internal Database URL\n   RUN_WORKER_IN_WEB = true\n   ADMIN_TOKEN = long-random-secret\n4) Save Changes → Manual Deploy / Redeploy\n5) After the deploy finishes open https://YOUR-SERVICE.onrender.com/health\n   Expected version: 1.131.0"}, {"key": "cloudflare", "title": "Cloudflare Worker", "badge": "Dashboard setup", "body": "Cloudflare Dashboard → Workers & Pages → your Worker\nSettings → Variables and Secrets:\n  VAULT_SECRET = long-random-secret\nBindings:\n  D1 DB binding name = DB\n  Queue binding name = JOBS\nDeployments → Redeploy\nAfter redeploy open https://YOUR-WORKER.workers.dev/api/version\n  Expected version: 1.131.0\n  WORKER_VERSION in wrangler.toml is kept in sync by: npm run version:sync"}, {"key": "vps", "title": "Ubuntu/Debian VPS", "badge": "Production Node", "body": "sudo apt update\nsudo apt install -y git curl nginx build-essential postgresql postgresql-contrib\ncurl -fsSL https://deb.nodesource.com/setup_20.x | sudo -E bash -\nsudo apt install -y nodejs\ngit clone --branch arena/01a0803e-new https://github.com/fazilatma/new.git /opt/scraper4-new\ncd /opt/scraper4-new/cloudflare-scraper4\nnpm install\nnode scripts/esbuild-check.mjs\nnpm run version:check\n# Expected: 1.131.0\nnpm run deployer:ui\n# Browser engines for JavaScript-only shops (skip on a tiny VPS: ~400MB).\nsudo apt-get install -y chromium || sudo apt-get install -y chromium-browser || true\nnpm run browsers:install"}, {"key": "api", "title": "API examples", "badge": "Automation", "body": "curl -X POST http://127.0.0.1:3000/api/profiles/PROFILE_ID/run -H 'content-type: application/json' -d '{\"target\":\"none\",\"pages\":1,\"details\":true,\"persist\":true}'\ncurl -X POST http://127.0.0.1:3000/api/profiles/PROFILE_ID/run -H 'content-type: application/json' -d '{\"extract\":false,\"target\":\"both\",\"limit\":100}'\ncurl -s http://127.0.0.1:3000/health\n# Expected version: 1.131.0\n# Manual sync = extract + details + push to WooCommerce and every active Basalam stall:\ncurl -X POST http://127.0.0.1:3000/api/profiles/PROFILE_ID/scrape -H 'content-type: application/json' -d '{\"target\":\"both\"}'\n# AI description generator (on by default, uses the master model, fills only empty fields):\ncurl -s http://127.0.0.1:3000/api/ai/description-settings\ncurl -X POST http://127.0.0.1:3000/api/ai/description-settings -H 'content-type: application/json' -d '{\"enabled\":true}'\ncurl -X POST http://127.0.0.1:3000/api/profiles/PROFILE_ID/ai-descriptions -H 'content-type: application/json' -d '{\"limit\":25}'\n# The same three routes exist on the Cloudflare Worker: swap the host for your workers.dev URL."}, {"key": "cpanel", "title": "cPanel Shared Hosting", "badge": "Node.js Selector + Passenger", "body": "# cPanel shared hosting (Setup Node.js App + Phusion Passenger)\n# Full walkthrough: CPANEL-SHARED-HOSTING.md\n\n# 1) BUILD LOCALLY - shared hosting rarely has RAM to build.\ngit clone https://github.com/fazilatma/new.git\ncd new/cloudflare-scraper4\nnpm install\nnpm run render:build\nnpm run version:check          # Expected: 1.131.0\n\n# 2) UPLOAD to a folder OUTSIDE public_html, e.g. /home/USER/scraper4 :\n#    render-dist/  package.json  scripts/basalam-sdk-bridge.py  scripts/cpanel-app.js\n#    Never upload node_modules (native files are OS-specific) or data/ storage/.\n\n# 3) Rename scripts/cpanel-app.js to app.js in the application root.\n\n# 4) cPanel -> Setup Node.js App -> Create Application\n#    Node.js version   : 22 or newer   (needed for the built-in node:sqlite)\n#    Application root  : scraper4      (NOT inside public_html)\n#    Application URL   : your domain or subdomain\n#    Startup file      : app.js\n#    Application mode  : Production\n\n# 5) Environment variables (same screen). Do NOT set PORT - Passenger assigns it.\n#    ADMIN_TOKEN=<long random string>\n#    VAULT_SECRET=<long random string>\n#    SCRAPER4_SQLITE_PATH=/home/USER/scraper4/data/scraper4.sqlite\n#    LOCAL_SCRAPER_AUTO_UPDATE=0\n#    BASALAM_PYTHON=/home/USER/virtualenv/scraper4py/3.11/bin/python\n\n# 6) Install dependencies. Use the activation line cPanel shows at the top:\nsource /home/USER/nodevenv/scraper4/22/bin/activate\ncd /home/USER/scraper4\nNODE_OPTIONS='--max-old-space-size=512' npm install --omit=dev\n\n# 7) OPTIONAL - official Basalam SDK (cPanel -> Setup Python App, 3.9+):\nsource /home/USER/virtualenv/scraper4py/3.11/bin/activate\npip install basalam-sdk\necho '{\"action\":\"probe\"}' | python /home/USER/scraper4/scripts/basalam-sdk-bridge.py\n\n# 8) Press Restart in cPanel, then verify:\n#    https://your-domain/health   -> {\"ok\":true,...,\"databaseReady\":true}\n\n# NOTES\n# - playwright/puppeteer/crawlee are NOT installable here (each downloads a\n#   ~300MB browser). They are lazy-loaded, so the cheerio/htmlrewriter engines\n#   still work. JavaScript-only shops need Render/VPS/Termux instead.\n# - No PM2/forever/systemd: Passenger is the process manager. Restart from cPanel\n#   (or touch tmp/restart.txt) after every code change.\n# - Node 20 cannot use node:sqlite -> set DATABASE_URL to PostgreSQL instead.\n\n# 9) Confirm the deployed build really is this version:\n#    curl -s https://your-domain/health | grep version   # Expected: 1.131.0"}];
