const menuGroupAt={0:'🧰 نگهداری و نسخه',3:'🔌 اتصال‌ها و سرویس‌ها',7:'📦 عملیات محصولات و سلامت',16:'🤖 اتوماسیون و گزارش'};

function installCommandText(key){if(key==='all')return INSTALL_COMMAND_GROUPS_CLIENT.map(x=>'# '+x.title+' — '+x.badge+String.fromCharCode(10)+x.body).join(String.fromCharCode(10,10));const item=INSTALL_COMMAND_GROUPS_CLIENT.find(x=>x.key===key);return item?item.body:''}
function installScriptName(item){const key=String(item?.key||'install');if(key.includes('powershell'))return 'scraper4-install-windows.ps1';if(key.includes('cmd'))return 'scraper4-install-windows.cmd';if(key.includes('windows'))return 'scraper4-install-windows.ps1';if(key.includes('termux'))return 'scraper4-install-termux.sh';if(key.includes('vps'))return 'scraper4-install-vps.sh';if(key.includes('docker'))return 'scraper4-database-docker.sh';if(key.includes('cpanel'))return 'scraper4-install-cpanel.sh';return 'scraper4-'+key.replace(/[^a-z0-9_-]+/gi,'-')+'.txt'}
function windowsLauncherCmd(ps1Text,scriptName){const b64=btoa(unescape(encodeURIComponent(ps1Text))),chunks=[];for(let i=0;i<b64.length;i+=400)chunks.push(b64.slice(i,i+400));const L=[];L.push('@echo off');L.push('setlocal EnableExtensions EnableDelayedExpansion');L.push('REM Scraper4 - double-click launcher.');L.push('REM Windows opens .ps1 files in Notepad instead of running them, so this .cmd');L.push('REM carries the installer inside it and runs it with -ExecutionPolicy Bypass.');L.push('title Scraper4 installer');L.push('cd /d "%~dp0"');L.push('set "B64="');for(const c of chunks)L.push('set "B64=!B64!'+c+'"');L.push('set "PS1=%TEMP%\\'+scriptName+'"');L.push('set "PSEXE=powershell"');L.push('where pwsh >nul 2>&1 && set "PSEXE=pwsh"');L.push('"%PSEXE%" -NoProfile -ExecutionPolicy Bypass -Command "[IO.File]::WriteAllText($env:PS1, [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($env:B64)))"');L.push('if not exist "%PS1%" (echo [X] Could not unpack the installer.& pause& exit /b 1)');L.push('echo ==========================================================');L.push('echo   Scraper4 installer   ^(engine: %PSEXE%^)');L.push('echo ==========================================================');L.push('echo.');L.push('"%PSEXE%" -NoProfile -ExecutionPolicy Bypass -File "%PS1%"');L.push('set "RC=%ERRORLEVEL%"');L.push('del "%PS1%" >nul 2>&1');L.push('echo.');L.push('if "%RC%"=="0" (echo [OK] Installer finished successfully.) else (echo [X] Installer exited with code %RC%.)');L.push('echo.');L.push('echo This window stays open so you can read the output.');L.push('pause');L.push('endlocal');return L.join('\r\n')+'\r\n'}
function saveBlobAs(text,name,mime){const blob=new Blob([text],{type:mime||'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function downloadInstallScript(key){const item=INSTALL_COMMAND_GROUPS_CLIENT.find(x=>x.key===key);if(!item)return;const name=installScriptName(item);saveBlobAs(item.body,name,'text/plain;charset=utf-8');if(name.endsWith('.ps1')){const launcherName=name.replace(/\.ps1$/,'-RUN-ME.cmd');setTimeout(()=>{saveBlobAs(windowsLauncherCmd(item.body,name),launcherName,'application/octet-stream');notice('دو فایل دانلود شد: '+launcherName+' را دابل\u200cکلیک کنید (فایل .ps1 با دابل\u200cکلیک اجرا نمی\u200cشود).','ok')},400)}else notice('فایل اجرای این محیط دانلود شد: '+name,'ok')}
function renderInstallCommandCards(){const root=$('installCommandCards');if(!root)return;root.innerHTML=INSTALL_COMMAND_GROUPS_CLIENT.map(x=>'<details class="install-command-card"><summary><b>'+esc(x.title)+'</b> <span class="chip">'+esc(x.badge)+'</span></summary><pre>'+esc(x.body)+'</pre><div class="menu-actions"><button type="button" class="btn btn-blue btn-sm" data-copy-install="'+escAttr(x.key)+'">📋 Copy all</button><button type="button" class="btn btn-green btn-sm" data-download-install="'+escAttr(x.key)+'">⬇ دانلود فایل اجرا</button><span class="copy-flash" id="copyInstall-'+escAttr(x.key)+'"></span></div></details>').join('');const all=$('installAllCommands');if(all)all.value=installCommandText('all')}
async function copyInstallCommand(key){const text=installCommandText(key);if(!text)return;try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();document.execCommand('copy');ta.remove()}const el=key==='all'?$('installCopyAllStatus'):$('copyInstall-'+key);if(el){el.textContent='کپی شد';setTimeout(()=>{if(el)el.textContent=''},1800)}notice('دستورها کپی شد.','ok')}catch(error){notice('کپی خودکار ممکن نشد؛ متن را دستی انتخاب کنید.','error')}};
function initMenu(){$('menuSections').innerHTML='<div class="drawer-guide"><b>ابزارهای تکمیلی</b>کارهای اصلی در شش بخش پایین صفحه‌اند. اینجا فقط تنظیمات تخصصی و عملیات نگهداری، براساس موضوع گروه‌بندی شده‌اند.</div>'+menuDefs.map(([title,key,desc,content],index)=>(menuGroupAt[index]?'<div class="menu-group-label">'+menuGroupAt[index]+'</div>':'')+'<section class="menu-section" data-menu="'+key+'"><button class="menu-title"><span>'+title+'</span><i>▼</i></button><div class="menu-content"><details class="menu-desc"><summary>ℹ️ توضیح این بخش</summary><p class="menu-text">'+desc+'</p></details>'+content+'</div></section>').join('');renderThemeSwatches();renderInstallCommandCards()}
function initFields(){ $('selectorGrid').innerHTML=listFields.map(([id,label])=>fieldHtml(id,label,id==='container'?'li.product':id==='title'?'h2':id==='price'?'.price':id==='link'?'a[href]':'img')).join(''); $('detailGrid').innerHTML=detailFields.map(([id,label])=>fieldHtml(id,label,'')).join('');galModeChanged();updateDetailSummary();initAutoSave() }
function galModeChanged(){const mode=$('galMode').value;$('galAutoBox').hidden=mode!=='auto';$('galManualBox').hidden=mode!=='manual';$('galNumberBox').hidden=mode!=='number';$('galCommon').hidden=mode==='off'||mode==='variations'?mode==='off':false;if($('detailSelectionSummary'))updateDetailSummary()}
function galleryConfig(){return{mode:$('galMode').value,box:$('galBox').value.trim(),selectors:$('galSelectors').value.trim(),variations:($('sel-variations')&&$('sel-variations').value.trim())||'',pattern:$('galPattern').value.trim(),from:Number($('galFrom').value)||0,to:Number($('galTo').value)||10,max:Math.max(1,Math.min(30,Number($('galMax').value)||10)),skip_first:$('galSkipFirst').checked}}
function loadGallery(cfg={}){$('galMode').value=cfg.mode||'off';$('galBox').value=cfg.box||'';$('galSelectors').value=cfg.selectors||'';$('galPattern').value=cfg.pattern||'';$('galFrom').value=cfg.from??1;$('galTo').value=cfg.to??10;$('galMax').value=cfg.max??10;$('galSkipFirst').checked=!!cfg.skip_first;galModeChanged()}
function gallerySelector(cfg=galleryConfig()){if(cfg.mode==='variations')return cfg.variations||$('sel-variations')?.value.trim()||'';if(cfg.mode==='auto')return cfg.box;if(cfg.mode==='manual')return cfg.selectors;if(cfg.mode==='number'&&cfg.pattern.includes('{n}'))return Array.from({length:Math.max(0,Math.min(cfg.to,cfg.from+60)-cfg.from+1)},(_,i)=>cfg.pattern.replaceAll('{n}',String(cfg.from+i))).join('\n');return''}
function fieldHtml(id,label,value){return '<div class="sel-item" id="wrap-'+id+'"><div class="sel-title"><b>'+label+'</b><span>CSS</span></div><input id="sel-'+id+'" dir="ltr" value="'+escAttr(value)+'"><div id="result-'+id+'" class="sel-result">—</div></div>'}
const INSTALL_COMMAND_GROUPS_CLIENT=INSTALL_COMMAND_GROUPS;
const headers=()=>({'content-type':'application/json'});
async function api(path,options={}){const response=await fetch(U(path),{...options,headers:{...headers(),...(options.headers||{})}}),text=await response.text();let data;try{data=JSON.parse(text)}catch{data={error:text||'HTTP '+response.status}}if(!response.ok)throw Error(data.detail||data.error||'HTTP '+response.status);return data}
function renderRuntimeLibraries(data){const el=$('runtimeInstalledLibraries');if(!el)return;const groups=data.groups||[];el.innerHTML=groups.map(g=>'<article class="install-command-card"><h4>'+esc(g.label||'گروه')+' <span class="chip">'+esc(data.environment||'runtime')+'</span></h4><pre>'+((g.items||[]).map(item=>(item.available?'✅ ':'❌ ')+item.name+(item.version?' @ '+item.version:'')+(item.source?' — '+item.source:'')+(item.note?' — '+item.note:'')).map(esc).join('\n')||'—')+'</pre></article>').join('')||'<article class="install-command-card"><h4>بدون داده</h4><pre>API چیزی برنگرداند.</pre></article>'}
async function loadRuntimeLibraries(){const el=$('runtimeInstalledLibraries');if(!el)return;try{renderRuntimeLibraries(await api('/api/runtime/libraries'))}catch(error){el.innerHTML='<article class="install-command-card"><h4>خطا در استعلام</h4><pre>'+esc(error.message||String(error))+'</pre></article>'}}
function notice(message,kind='ok',persist=false){const el=$('notice');el.className='notice show '+kind;el.textContent=message;clearTimeout(notice.timer);if(!persist)notice.timer=setTimeout(()=>el.classList.remove('show'),6000)}
function output(value){$('out').textContent=typeof value==='string'?value:JSON.stringify(value,null,2)}
function busy(button,on){button.disabled=on;if(on){button.dataset.old=button.textContent;button.textContent='در حال انجام…'}else if(button.dataset.old)button.textContent=button.dataset.old}
function drawer(open){$('drawer').classList.toggle('open',open);$('drawerOverlay').classList.toggle('open',open);$('hamburgerBtn').classList.toggle('active',open);if(open&&state.selected)for(const id of ['retireProfile','reconProfile','bulkProfile','photoProfile'])if($(id)&&!$(id).value)$(id).value=state.selected}
function nestedGet(obj,path){return path.split('.').reduce((value,key)=>value?.[key],obj)}
function nestedSet(obj,path,value){const keys=path.split('.');let node=obj;keys.slice(0,-1).forEach(key=>node=node[key]||(node[key]={}));node[keys.at(-1)]=value}
