function aiKeySuffixLabel(i){return i>0?' [K'+fa(i+1)+']':''}
function aiProviderKeyCount(p){return Array.isArray(p?.apiKeys)&&p.apiKeys.length?p.apiKeys.filter(k=>String(k||'').trim()).length:(p?.apiKey?1:0)}
function renderAiTestEstimate(){
  const el=$('aiTestEstimate');if(!el)return;
  const ai=state.connections?.ai||{},only=Boolean($('aiTestOnlyUntested')?.checked),providers=(ai.providers||[]).filter(p=>p.enabled!==false),candidates=new Set(Array.isArray(ai.candidates)?ai.candidates.map(String):[]);
  let models=0,entries=0,keyProviders=0;
  for(const p of providers){
    const list=(p.models||[]).filter(m=>!only||(candidates.has(p.id+'::'+m)&&aiChatCompatibleModel(m)));
    const keys=Math.max(1,aiProviderKeyCount(p));
    models+=list.length;entries+=list.length*keys;if(keys>1&&list.length)keyProviders++;
  }
  el.innerHTML=providers.length?('ورودی‌های تست: <b>'+fa(entries)+'</b> ('+fa(models)+' مدل در '+fa(providers.length)+' ارائه‌دهنده)'+(keyProviders?' · کلیدهای اضافه در '+fa(keyProviders)+' ارائه‌دهنده: هر مدل با پسوند [K۲]/[K۳] جدا تست می‌شود':'')):'هنوز ارائه‌دهندهٔ روشنی ثبت نشده است.';
}
function aiIsCloudflareBase(url){return /\/accounts\/[^/]+\/ai\/run(?:\/|$)/i.test(String(url||'').trim())}
function aiCloudflareAccountFromBase(url){return String(url||'').trim().match(/\/accounts\/([^/]+)\/ai\/run(?:\/|$)/i)?.[1]||''}
function aiCloudflareBaseFromParts(accountId,token){const account=String(accountId||'').trim(),t=String(token||'').trim();if(!account||!t)return '';return 'https://api.cloudflare.com/client/v4/accounts/'+encodeURIComponent(account)+'/ai/run/'}
function aiDedicatedEndpoint(model){const value=String(model||'').toLowerCase();return value==='mistral-ocr-latest'?'OCR':value==='mistral-embed'?'Embedding':''}
