async function activityPoll(){clearTimeout(activityTimer);if(!activityVisible||!document.getElementById('resultModal'))return;try{const d=await api('/api/activity');activityData=d;if(!quotaData||Date.now()-(quotaLoadedAt||0)>60000){quotaLoadedAt=Date.now();loadQuota()}renderActivity(d);if(activityVisible)activityTimer=setTimeout(activityPoll,3000)}catch{const body=$('activityBody');if(body)body.innerHTML=quota+'<div class="result-summary bad"><b>خطا در دریافت وضعیت</b><br>'+esc('دریافت فعالیت‌ها ناموفق بود.')+'</div>'}}
// The unified reconciliation preview/apply run inside a single HTTP request,
// so they never create a server-side background run. The task manager showed
// nothing while they worked, which made the button look dead. Track them
// client-side and merge them into the same list the poller renders.
const localTasks=new Map();
function localTaskStart(key,name,detail){
 localTasks.set(key,{kind:'local:'+key,name:name,status:'running',phase:detail||'',progress:10,detail:detail||'',local:true});
 if(activityData)renderActivity(activityData);
}
function localTaskEnd(key,ok,detail){
 const task=localTasks.get(key);if(!task)return;
 task.status=ok?'done':'failed';task.progress=100;task.detail=detail||task.detail;task.phase=detail||task.phase;
 if(activityData)renderActivity(activityData);
 setTimeout(()=>{localTasks.delete(key);if(activityData)renderActivity(activityData)},ok?8000:15000);
}
function activityStatusBadge(status){return{queued:'⏳ در صف',running:'⚙️ در حال اجرا',paused:'⏸ متوقف',done:'✅ کامل',failed:'❌ خطا'}[status]||status||'—'}
function activityBar(progress){const p=Math.max(0,Math.min(100,Number(progress)||0));return '<div class="progress" style="margin:2px 0 0"><div class="bar" style="width:'+p+'%"></div></div>'}
function activityJobControls(j,index,total){return '<span class="activity-moves"><span class="activity-handle" title="با کشیدن جابه‌جا کنید">⠿</span><span class="chip" style="background:#1e3a5f;color:#93c5fd">اولویت '+fa(index+1)+'</span><button class="activity-move" data-activity-up="'+escAttr(j.id)+'" title="یک رتبه بالاتر" '+(index===0?'disabled':'')+'>▲</button><button class="activity-move" data-activity-down="'+escAttr(j.id)+'" title="یک رتبه پایین‌تر" '+(index===total-1?'disabled':'')+'>▼</button></span>'}
function activityJobRow(j,reorderable,index,total){const moves=reorderable?activityJobControls(j,index,total):'';const del='<button class="activity-move" data-job-delete="'+escAttr(j.id)+'" title="حذف کار" '+(j.status==='running'?'disabled':'')+'>🗑</button>';return '<div class="activity-job'+(reorderable?' activity-queued':'')+'"'+(reorderable?' draggable="true" data-job-id="'+escAttr(j.id)+'"':'')+'><div class="activity-job-head">'+moves+del+'<b>'+esc((j.kind==='sync'?'همگام‌سازی':'استخراج'))+' · '+esc(j.target||'')+'</b><span class="chip">'+esc(activityStatusBadge(j.status))+'</span></div>'+activityBar(j.progress)+'<div class="activity-job-meta">'+esc(j.detail||'')+(j.engine?' · موتور: '+esc(j.engine):'')+(j.speedPerMinute!==undefined?' · '+fa(j.speedPerMinute)+' محصول/دقیقه':'')+(j.error?' <span style="color:#fca5a5">'+esc(j.error)+'</span>':'')+'</div></div>'}
function activityRunControls(r,index,total){return '<span class="activity-moves"><span class="activity-handle" title="با کشیدن جابه‌جا کنید">⠿</span><span class="chip" style="background:#1e3a5f;color:#93c5fd">اولویت '+fa(index+1)+'</span><button class="activity-move" data-run-up="'+escAttr(r.kind)+'" title="یک رتبه بالاتر" '+(index===0?'disabled':'')+'>▲</button><button class="activity-move" data-run-down="'+escAttr(r.kind)+'" title="یک رتبه پایین‌تر" '+(index===total-1?'disabled':'')+'>▼</button></span>'}
function activityRunRow(r,reorderable,index,total){const moves=reorderable?activityRunControls(r,index,total):'';const del=r.local?'':'<button class="activity-move" data-run-delete="'+escAttr(r.kind)+'" title="پاک‌کردن این اجرا">🗑</button>';return '<div class="activity-run'+(reorderable?' activity-queued':'')+'" data-activity-run="'+escAttr(r.kind)+'"'+(reorderable?' draggable="true" data-run-kind="'+escAttr(r.kind)+'"':'')+(r.local?'':' title="برای مشاهدهٔ پنجرهٔ این اجرا کلیک کنید"')+'><div class="activity-run-head"><b>'+esc(r.name)+'</b><span class="chip">'+esc(activityStatusBadge(r.status))+' · '+esc(r.phase==='quota'?'سهمیهٔ نوشتن تمام شده':r.phase||'')+'</span></div>'+activityBar(r.progress)+(moves?'<div style="margin-top:4px">'+moves+'</div>':'')+'<div class="activity-run-meta">'+esc(r.detail||'')+'</div><div style="margin-top:4px">'+del+'</div></div>'}
/**
 * D1 daily-quota bar. The free plan is a hard ceiling (5,000,000 rows read and
 * 100,000 rows written per UTC day); once it is hit every query fails, so the
 * numbers belong where the running work is visible.
 */
let quotaData=null,quotaLoadedAt=0;
function renderQuotaBar(){
  if(!quotaData||!quotaData.d1)return '';
  const d=quotaData.d1,read=Math.min(100,Number(d.percent?.rowsRead)||0),write=Math.min(100,Number(d.percent?.rowsWritten)||0);
  const tone=v=>v>=90?'#f87171':v>=70?'#fbbf24':'#34d399';
  const row=(label,used,total,pct)=>'<div class="quota-row"><span class="quota-label">'+label+'</span>'
    +'<span class="quota-track"><span class="quota-fill" style="width:'+pct+'%;background:'+tone(pct)+'"></span></span>'
    +'<span class="quota-num">'+fa(used)+' / '+fa(total)+' ('+fa(Math.round(pct))+'٪)</span></div>';
  const reqPct=Math.min(100,Number(d.percent?.requests)||0),subPct=Math.min(100,Number(d.percent?.peakSubrequests)||0);
  return '<div class="quota-box"><b>📊 سهمهٔ روزانهٔ کلودفلر</b>'
    +'<div class="quota-group">پایگاه‌داده (D1)</div>'
    +row('خواندن',d.rowsRead||0,d.limits?.rowsRead||0,read)
    +row('نوشتن',d.rowsWritten||0,d.limits?.rowsWritten||0,write)
    +'<div class="quota-group">اجرای Worker (شامل هوش مصنوعی)</div>'
    +row('اجراها',d.requests||0,d.limits?.requests||0,reqPct)
    +row('بیشینهٔ درخواست بیرونی در یک اجرا',d.peakSubrequests||0,d.limits?.subrequestsPerInvocation||0,subPct)
    +'<div class="quota-note">عملیات هوش مصنوعی در D1 چیزی نمی‌نویسد، اما هر تماس با مدل یک «درخواست بیرونی» است؛ سقف آن ۵۰ در هر اجراست.</div>'
    +'<div class="quota-note">صفر شدن شمارنده: '+esc(String(d.resetsAt||'').slice(0,16).replace('T',' '))+' UTC · فقط عملیات همین Worker شمرده می‌شود.</div></div>';
}
async function loadQuota(){
  try{const d=await api('/api/quota');quotaData=d;if(activityData)renderActivity(activityData)}catch{/* the panel works without it */}
}
function renderActivity(d){const body=$('activityBody');if(!body)return;if(activityDragging)return;
 const counts=d.counts||{},cron=d.cron||{},activeJobs=(d.activeJobs||[]),runs=(d.runs||[]),lastJobs=(d.lastJobs||[]);
 const queuedJobs=activeJobs.filter(j=>j.status==='queued'),runningJobs=activeJobs.filter(j=>j.status!=='queued');
 const quota=renderQuotaBar();
 const summary='<div class="activity-stats">'
  +'<div class="activity-stat"><b>'+fa(counts.profiles||0)+'</b><span>پروفایل</span></div>'
  +'<div class="activity-stat"><b>'+fa(counts.jobs||0)+'</b><span>کل کارها</span></div>'
  +'<div class="activity-stat'+(counts.active?' active':'')+'"><b>'+fa(counts.active||0)+'</b><span>فعال در صف/اجرا</span></div>'
  +'<div class="activity-stat'+(counts.runningRuns?' active':'')+'"><b>'+fa(counts.runningRuns||0)+'</b><span>اجرای پس‌زمینه</span></div>'
  +'<div class="activity-stat"><b>'+(cron.held?'🟢':'⚪')+'</b><span>کران'+(cron.ageSec!=null?' '+fa(cron.ageSec)+'ث':cron.lastTick?' —':'')+'</span></div>'
  +'<div class="activity-stat"><b dir="ltr">'+esc(d.version||'')+'</b><span>نسخه</span></div>'
  +'</div>';
 const runs2=[...Array.from(localTasks.values()),...runs];
 const queuedRuns=runs2.filter(r=>r.status==='queued'),otherRuns=runs2.filter(r=>r.status!=='queued');
 const runsHtml=runs2.length?('<h3>🧵 اجراهای پس‌زمینه به ترتیب اولویت ('+fa(queuedRuns.length)+')</h3>'+(queuedRuns.length?'<div class="activity-runs">'+queuedRuns.map((r,i)=>activityRunRow(r,true,i,queuedRuns.length)).join('')+'</div>':'<div class="empty compact">اجرای در انتظاری نیست.</div>')+(otherRuns.length?'<h3>⚙️ سایر اجراها ('+fa(otherRuns.length)+')</h3><div class="activity-runs">'+otherRuns.map(r=>activityRunRow(r,false,0,0)).join('')+'</div>':'')):'<div class="empty compact">اجرای پس‌زمینه‌ای فعال نیست.</div>';
 const jobsHtml='<h3>📋 صف اجرا به ترتیب اولویت ('+fa(queuedJobs.length)+')</h3>'+(queuedJobs.length?'<div class="activity-jobs">'+queuedJobs.map((j,i)=>activityJobRow(j,true,i,queuedJobs.length)).join('')+'</div>':'<div class="empty compact">کاری در صف نیست.</div>')+(runningJobs.length?'<h3>⚙️ در حال اجرا ('+fa(runningJobs.length)+')</h3><div class="activity-jobs">'+runningJobs.map(j=>activityJobRow(j,false,0,0)).join('')+'</div>':'');
 const recent='<h3>🕘 آخرین کارها'+(lastJobs.length?' <button class="activity-move" data-clear-finished title="پاک‌کردن همهٔ کارهای پایان‌یافته">🗑 پاک‌سازی</button>':'')+'</h3>'+(lastJobs.length?'<div class="activity-jobs">'+lastJobs.map(j=>'<div class="activity-job"><div class="activity-job-head"><b>'+esc((j.kind==='sync'?'همگام‌سازی':'استخراج'))+'</b><span class="chip">'+esc(activityStatusBadge(j.status))+'</span><button class="activity-move" data-job-delete="'+escAttr(j.id)+'" title="حذف کار">🗑</button></div><div class="activity-job-meta">'+esc(j.phase||'')+' · '+esc((j.at||'').replace('T',' ').slice(0,19))+(j.error?' <span style="color:#fca5a5">'+esc(j.error)+'</span>':'')+'</div></div>').join('')+'</div>':'<div class="empty compact">کاری ثبت نشده است.</div>');
 body.innerHTML='<div class="activity-hint">به‌روزرسانی خودکار هر ۳ ثانیه — با بستن این پنجره متوقف می‌شود (سایت سنگین نمی‌شود). اجراهای پس‌زمینه و کارهای صف را با کشیدن یا ▲▼ اولویت‌بندی کنید (بالایی زودتر پردازش می‌شود)؛ با کلیک روی هر اجرا وارد پنجرهٔ همان اجرا می‌شوید و با 🗑 می‌توانید کارها و اجراها را حذف کنید.<span id="activitySaveStatus" class="activity-save-status"></span></div>'+d1QuotaHtml(d.quota&&d.quota.d1)+((d.quota&&d.quota.writeExceeded)?'<div class="result-summary bad" style="margin-bottom:10px"><b>⚠️ سهمیهٔ نوشتن D1 تمام شده است</b><br>پلن رایگان Cloudflare D1 اجازهٔ ۱۰۰٬۰۰۰ عملیات نوشتن در هر شبانه‌روز می‌دهد (ریست ۰۰:۰۰ UTC). تا آن زمان هیچ فعالیت پس‌زمینه‌ای جلو نمی‌رود؛ پس از ریست خودکار ادامه می‌یابند. برای ادامهٔ فوری، به پلن پولی Workers ارتقا دهید.</div>':'')+summary+runsHtml+jobsHtml+recent;
}

function d1QuotaHtml(u){
  if(!u||!u.limits)return '';
  var w=u.percent&&u.percent.rowsWritten||0,r=u.percent&&u.percent.rowsRead||0;
  var worst=Math.max(w,r),tone=worst>=90?'bad':worst>=70?'warn':'ok';
  var bar=function(label,used,limit,pct){
    var color=pct>=90?'#f87171':pct>=70?'#fbbf24':'#34d399';
    return '<div style="margin-top:6px"><div style="display:flex;justify-content:space-between;font-size:12px"><span>'+label+'</span><span>'+fa(used.toLocaleString('en-US'))+' / '+fa(limit.toLocaleString('en-US'))+' · '+fa(pct)+'٪</span></div>'+
      '<div style="height:7px;background:#1e293b;border-radius:4px;overflow:hidden;margin-top:3px"><div style="height:100%;width:'+Math.min(100,pct)+'%;background:'+color+'"></div></div></div>';
  };
  return '<div class="result-summary '+tone+'" style="margin-bottom:10px"><b>📊 مصرف امروز پایگاه دادهٔ D1 (پلن رایگان)</b>'+
    bar('سطرهای نوشته‌شده',u.rowsWritten,u.limits.rowsWritten,w)+
    bar('سطرهای خوانده‌شده',u.rowsRead,u.limits.rowsRead,r)+
    '<div style="font-size:11px;opacity:.8;margin-top:6px">این عدد فقط مصرف همین Worker است و از روی گزارش دقیق هر کوئری شمرده می‌شود؛ مصرف داشبورد Cloudflare یا ابزارهای دیگر در آن نیست. ریست: ۰۰:۰۰ UTC</div></div>';
}

function applyBasalamAutofill(d){const a=(d&&d.summary&&d.summary.autofill)||{};const filled=[];const set=(id,value,label)=>{const el=$(id);if(!el)return;const next=String(value==null?'':value).trim();if(!next)return;if(String(el.value||'').trim()===next)return;el.value=next;el.dispatchEvent(new Event('input',{bubbles:true}));filled.push(label)};set('bsVid',a.vendorId,'شناسهٔ غرفه');set('bsPD',a.preparationDays,'روزهای آماده‌سازی');if(a.vendorId)state.connections.basalam.vendorId=String(a.vendorId);if(a.preparationDays)state.connections.basalam.preparationDays=Number(a.preparationDays);return filled}
