function renderStatus(status,health){$('statProfiles').textContent=fa(state.profiles.length);$('statRunning').textContent=fa((status.jobs||[]).filter(j=>['queued','running'].includes(j.status)).length);$('statFailed').textContent=fa((status.jobs||[]).filter(j=>j.status==='failed').length);setState('dbState',health.databaseReady);setState('wooState',status.connections.woo);setState('basalamState',status.connections.basalam);setState('workerState',health.workerInWeb)}
function setState(id,on){const el=$(id);el.textContent=on?'فعال':'غیرفعال';el.className=on?'on':'off'}
function renderProfiles(){const box=$('profileList');box.innerHTML=state.profiles.map(p=>'<div class="profile '+(state.selected===p.id?'selected':'')+'"><div class="profile-title"><span>'+esc(p.name)+'</span><span class="chip">'+(p.enabled?'فعال':'خاموش')+'</span></div><div class="profile-url">'+esc(p.url)+'</div><div class="profile-meta"><span class="chip">'+fa(p.pages)+' صفحه</span><span class="chip">'+(p.intervalMinutes?fa(p.intervalMinutes)+' دقیقه':'دستی')+'</span><span class="chip">موتور: '+esc(p.extractionEngine||'auto')+'</span>'+(p.extractionEngineMaster?'<span class="chip">مستر: '+esc(p.extractionEngineMaster)+'</span>':'')+(p.syncWoo?'<span class="chip">Woo</span>':'')+(p.syncBasalam?'<span class="chip">Basalam</span>':'')+'</div><div class="profile-actions"><button class="btn btn-blue btn-sm" data-paction="scrape" data-id="'+escAttr(p.id)+'">▶ استخراج</button><button class="btn btn-green btn-sm" data-paction="sync" data-id="'+escAttr(p.id)+'">↥ ارسال</button><button class="btn btn-gray btn-sm" data-paction="diagnose" data-id="'+escAttr(p.id)+'">🩺 عیب‌یابی</button><button class="btn btn-purple btn-sm" data-paction="edit" data-id="'+escAttr(p.id)+'">✎ ویرایش</button><button class="btn btn-red btn-sm" data-paction="delete" data-id="'+escAttr(p.id)+'">حذف</button></div></div>').join('')||'<div class="empty">پروفایلی وجود ندارد؛ از تب سلکتورها بسازید.</div>';syncProfileSelects()}
async function profileEngineChange(select){const id=select.dataset.profileEngine,profile=state.profiles.find(p=>p.id===id);if(!profile)return;const previous=profile.extractionEngine||'auto',next=select.value;if(previous===next)return;try{const saved=await api('/api/profiles',{method:'POST',body:JSON.stringify({...profile,extractionEngine:next,extractionEngineMaster:'',extractionEngineMs:0})});Object.assign(profile,saved.profile||{}, {extractionEngine:next});if(state.selected===id&&$('extractionEngine'))$('extractionEngine').value=next;notice('موتور استخراج پروفایل ذخیره شد: '+next,'ok');await refreshProfiles()}catch(error){select.value=previous;notice(error.message,'error')}}
function syncProfileSelects(preferred=''){const options='<option value="">— انتخاب پروفایل —</option>'+state.profiles.map(p=>'<option value="'+escAttr(p.id)+'">'+esc(p.name)+'</option>').join(''),preferredId=state.profiles.some(p=>p.id===preferred)?preferred:'';for(const id of ['productProfile','transferProfile','photoProfile','homeProfile','settingsProfile','sendProfile','importProfile','aiDescProfile']){if(!$(id))continue;const current=preferredId||$(id).value||(['settingsProfile','homeProfile','sendProfile','importProfile'].includes(id)?state.selected:'');$(id).innerHTML=(id==='photoProfile'?'<option value="">همهٔ پروفایل‌ها</option>':options);if(state.profiles.some(p=>p.id===current))$(id).value=current}}
function homeTargetFromProfile(profile){return profile?.syncWoo&&profile?.syncBasalam?'both':profile?.syncWoo?'woo':profile?.syncBasalam?'basalam':'none'}
function ensureHomeInterval(value){const select=$('homeSyncInterval'),wanted=String(Math.max(1,Number(value)||60));if(!select.querySelector('option[value="'+wanted+'"]'))select.insertAdjacentHTML('beforeend','<option value="'+escAttr(wanted)+'">هر '+fa(wanted)+' دقیقه (سفارشی)</option>');select.value=wanted}
function updateHomeSyncUi(){const enabled=$('homeSyncEnabled').checked;$('homeSyncInterval').disabled=!enabled;$('homeSyncStatus').textContent=enabled?'اجرای دوره‌ای هر '+fa($('homeSyncInterval').value)+' دقیقه فعال می‌شود.':'همگام‌سازی دوره‌ای خاموش است.';$('homeSyncStatus').classList.toggle('on',enabled)}
function applyHomeTarget(target){const value=['woo','basalam','both'].includes(target)?target:'none';$('homeSyncTarget').value=value;$('homeSyncWoo').checked=['woo','both'].includes(value);$('homeSyncBasalam').checked=['basalam','both'].includes(value)}
function updateHomeTargetFromChecks(){applyHomeTarget($('homeSyncWoo').checked&&$('homeSyncBasalam').checked?'both':$('homeSyncWoo').checked?'woo':$('homeSyncBasalam').checked?'basalam':'none')}
function engineBenchmarks(profile){return Array.isArray(profile?.extractionEngineBenchmarks)?profile.extractionEngineBenchmarks:[]}
function engineSpeedLabel(row){if(!row)return'';if(row.available===false)return' (در دسترس نیست)';if(row.error&&!row.products)return' (خطا)';return ' ('+fa(row.elapsedMs||0)+'ms · '+fa(row.products||0)+' محصول · '+fa(row.productsPerMinute||0)+'/دقیقه)'}
function applyEngineBenchmarkLabels(profile){const rows=new Map(engineBenchmarks(profile).map(row=>[row.engine,row]));for(const id of ['homeExtractionEngine','extractionEngine']){const sel=$(id);if(!sel)continue;for(const opt of sel.options){opt.dataset.base=opt.dataset.base||opt.textContent;opt.textContent=opt.dataset.base+engineSpeedLabel(rows.get(opt.value));}}}
function renderHomeProfile(profile){const p=profile||null;$('homeProfile').value=p?.id||'';$('homeProfileName').value=p?.name||'';$('homeUrl').value=p?.url&&!String(p.url).includes('import.invalid')?p.url:'';$('homePages').value=p?String(p.pages??0):'0';$('homePagination').value=p?.pagination||'query_page';$('homePaginationValue').value=p?.paginationValue||'page';applyEngineBenchmarkLabels(p);if($('homeExtractionEngine'))$('homeExtractionEngine').value=p?.extractionEngine||'auto';if($('extractionEngine'))$('extractionEngine').value=p?.extractionEngine||'auto';$('homeNoExtract').checked=!!p?.noExtract;$('homeNetworkIndirect').checked=!!p?.networkIndirect;$('homeSyncEnabled').checked=Boolean(p?.intervalMinutes);ensureHomeInterval(p?.intervalMinutes||60);applyHomeTarget(homeTargetFromProfile(p));updateHomeSyncUi()}
function homeProfileBody(){const existing=state.profiles.find(p=>p.id===$('homeProfile').value),syncEnabled=$('homeSyncEnabled').checked,noExtract=$('homeNoExtract').checked,url=$('homeUrl').value.trim().replace(/&amp;/g,'&'),name=$('homeProfileName').value.trim(),engine=$('homeExtractionEngine')?.value||existing?.extractionEngine||'auto';if(!name)throw Error('برای پروفایل یک نام بنویسید.');if(!url&&!noExtract)throw Error('آدرس صفحهٔ محصولات را وارد کنید یا حالت «بدون استخراج» را روشن کنید.');const selectors=existing?.selectors||{container:'li.product',title:'h2',price:'.price',link:'a[href]',image:'img'};return{...(existing||{}),id:existing?.id||undefined,name,url,enabled:true,pages:Math.max(0,Math.min(100,Number($('homePages').value)||0)),pagination:$('homePagination').value,paginationValue:$('homePaginationValue').value.trim()||'page',extractionEngine:engine,extractionEngineMaster:existing?.extractionEngine===engine?existing?.extractionEngineMaster:'',extractionEngineMs:existing?.extractionEngine===engine?existing?.extractionEngineMs:0,selectors,networkIndirect:$('homeNetworkIndirect').checked,noExtract,syncWoo:$('homeSyncWoo').checked,syncBasalam:$('homeSyncBasalam').checked,intervalMinutes:syncEnabled?Number($('homeSyncInterval').value)||60:0}}
async function saveHomeProfile(silent=false){const button=$('homeSaveProfile');busy(button,true);try{const result=await api('/api/profiles',{method:'POST',body:JSON.stringify(homeProfileBody())});rememberProfile(result.profile.id);await refreshProfiles();editProfile(result.profile.id,false);renderHomeProfile(result.profile);if(!silent)notice('پروفایل «'+result.profile.name+'» با همهٔ تنظیمات تب شروع ذخیره شد.');return result.profile}catch(error){notice(error.message,'error');throw error}finally{busy(button,false)}}
async function deleteHomeProfile(){const id=$('homeProfile').value;if(!id)throw Error('پروفایل ذخیره‌شده‌ای برای حذف انتخاب نشده است.');const profile=state.profiles.find(p=>p.id===id);if(!confirm('پروفایل «'+(profile?.name||id)+'» و محصولات آن حذف شود؟'))return;busy($('homeDeleteProfile'),true);try{await api('/api/profiles/'+encodeURIComponent(id),{method:'DELETE'});forgetRememberedProfile(id);clearForm();await refreshProfiles();renderHomeProfile(null);notice('پروفایل حذف شد.')}finally{busy($('homeDeleteProfile'),false)}}
function homeJobTarget(){const chosen=$('homeSyncTarget')?.value||'none';if(chosen&&chosen!=='none')return chosen;const woo=$('homeSyncWoo')?.checked??$('syncWoo')?.checked??false,basalam=$('homeSyncBasalam')?.checked??$('syncBasalam')?.checked??false;return woo&&basalam?'both':woo?'woo':basalam?'basalam':'none'}
async function startHomeExtraction(source){const button=$(source==='backend'?'homeBackend':'homeScrape');busy(button,true);try{const profile=await saveHomeProfile(true),kind=$('homeNoExtract').checked?'sync':'scrape';if(kind==='sync'&&$('homeSyncTarget').value==='none')throw Error('در حالت «بدون استخراج» حداقل یک مقصد ارسال را انتخاب کنید.');const data=await createJob(profile.id,kind,homeJobTarget(),false);output(data);const tgt=homeJobTarget(),where=tgt==='both'?'ووکامرس و همهٔ غرفه‌های فعال باسلام':tgt==='woo'?'ووکامرس':tgt==='basalam'?'همهٔ غرفه‌های فعال باسلام':'';notice(source==='backend'?'استخراج بک‌اند در صف قرار گرفت؛ وضعیت و دکمهٔ توقف در فهرست کارهای همین تب است.':('همگام‌سازی دستی شروع شد: استخراج فهرست، سپس جزئیات'+(where?('، سپس ارسال به '+where):' (بدون ارسال؛ مقصدی فعال نیست)')+'.'));await loadJobs(false)}catch(error){openResultModal('⚠️ شروع استخراج ناموفق بود',{ok:false,error:error.message})}finally{busy(button,false)}}
function renderHomeJobs(){const box=$('homeJobs');if(!box)return;const rows=(state.jobs||[]).slice(0,6),labels={queued:'در صف',running:'در حال اجرا',done:'کامل',failed:'ناموفق',cancelled:'متوقف'};box.innerHTML=rows.map(job=>{const running=['queued','running'].includes(job.status),failed=job.status==='failed',done=['done','failed','cancelled'].includes(job.status),progress=job.total?Math.max(0,Math.min(100,Math.round(Number(job.processed||0)/Number(job.total)*100))):(job.status==='done'?100:0);return '<div class="mini-job"><div class="mini-job-head"><b>'+(job.kind==='sync'?'ارسال':'استخراج')+' · '+esc(profileName(job.profileId))+'</b><span class="job-status s-'+escAttr(job.status)+'">'+esc(labels[job.status]||job.status)+'</span></div><small>'+esc(phaseLabel(job.phase))+' · '+fa(job.processed||0)+' از '+fa(job.total||0)+'</small><div class="mini-progress"><i style="width:'+progress+'%"></i></div>'+jobLiveMeta(job)+'<div class="profile-actions">'+(running?'<button class="btn btn-red btn-sm" data-home-job="stop" data-id="'+escAttr(job.id)+'">■ توقف</button>':'')+(failed?'<button class="btn btn-purple btn-sm" data-home-job="retry" data-id="'+escAttr(job.id)+'">↻ تلاش مجدد</button>':'')+(done?'<button class="btn btn-gray btn-sm" data-home-job="delete" data-id="'+escAttr(job.id)+'">حذف</button>':'')+'<button class="btn btn-blue btn-sm" data-home-job="open" data-id="'+escAttr(job.id)+'">جزئیات</button></div></div>'}).join('')||'<div class="empty compact">صف خالی است.</div>'}
function activateProfile(id){const value=String(id||''),profile=state.profiles.find(item=>item.id===value);if(!profile)return false;if($('profileId')?.value!==value)editProfile(value,false);else{rememberProfile(value);renderProfiles();syncProfileSelects(value)}return true}
function clearForm(){state.selected='';$('profileId').value='';$('name').value='';$('url').value='';$('pages').value='0';$('pagination').value='query_page';$('paginationValue').value='page';if($('extractionEngine'))$('extractionEngine').value='auto';$('interval').value='0';$('titleSuffix').value='';$('priceMode').value='none';$('priceValue').value='0';$('roundPrice').value='0';$('minPrice').value='0';$('wooCategoryId').value='0';$('basalamCategoryId').value='0';$('basalamFallbackCategoryIds').value='';$('detailSampleUrl').value='';$('enabled').checked=true;$('networkIndirect').checked=false;$('noExtract').checked=false;$('syncWoo').checked=false;$('syncBasalam').checked=false;listFields.forEach(([id])=>{$('sel-'+id).value=id==='container'?'li.product':id==='title'?'h2':id==='price'?'.price':id==='link'?'a[href]':'img';$('result-'+id).textContent='—'});detailFields.forEach(([id])=>{$('sel-'+id).value='';$('result-'+id).textContent='—'});loadGallery();$('editBadge').textContent='پروفایل جدید';renderProfiles();renderHomeProfile(null)}
function editProfile(id,navigate=true){const p=state.profiles.find(x=>x.id===id);if(!p)return;rememberProfile(id);$('profileId').value=p.id;$('name').value=p.name;$('url').value=p.url;$('pages').value=String(p.pages??0);$('pagination').value=p.pagination;$('paginationValue').value=p.paginationValue;if($('extractionEngine'))$('extractionEngine').value=p.extractionEngine||'auto';$('interval').value=p.intervalMinutes;$('titleSuffix').value=p.titleSuffix;$('priceMode').value=p.priceMode;$('priceValue').value=p.priceValue;if(!$('roundPrice').querySelector('option[value="'+p.roundPrice+'"]'))$('roundPrice').insertAdjacentHTML('beforeend','<option value="'+escAttr(p.roundPrice)+'">سفارشی: '+fa(p.roundPrice)+'</option>');$('roundPrice').value=p.roundPrice;$('minPrice').value=p.minPrice;$('wooCategoryId').value=p.wooCategoryId;$('basalamCategoryId').value=p.basalamCategoryId;$('basalamFallbackCategoryIds').value=(p.basalamFallbackCategoryIds||[]).join(', ');$('enabled').checked=p.enabled;$('networkIndirect').checked=!!p.networkIndirect;$('noExtract').checked=!!p.noExtract;$('syncWoo').checked=p.syncWoo;$('syncBasalam').checked=p.syncBasalam;[...listFields,...detailFields].forEach(([key])=>{$('sel-'+key).value=p.selectors[key]||''});loadGallery(p.gallery||{mode:p.selectors.gallery?'manual':'off',selectors:p.selectors.gallery||'',max:p.selectors.galleryMax||10,skip_first:!!p.selectors.gallerySkipFirst});$('editBadge').textContent='ویرایش: '+p.name;renderProfiles();syncProfileSelects(id);renderHomeProfile(p);if(navigate){tab('selector');subTab('basic')}}
function profileBody(){const selectors={};[...listFields,...detailFields].forEach(([key])=>selectors[key]=$('sel-'+key).value.trim());return{id:$('profileId').value||undefined,name:$('name').value.trim(),url:$('url').value.trim().replace(/&amp;/g,'&'),enabled:$('enabled').checked,pages:Number($('pages').value),pagination:$('pagination').value,paginationValue:$('paginationValue').value.trim(),extractionEngine:$('extractionEngine')?.value||'auto',intervalMinutes:Number($('interval').value),selectors,gallery:galleryConfig(),titleSuffix:$('titleSuffix').value,priceMode:$('priceMode').value,priceValue:Number($('priceValue').value),roundPrice:Number($('roundPrice').value),minPrice:Number($('minPrice').value),wooCategoryId:Number($('wooCategoryId').value),basalamCategoryId:Number($('basalamCategoryId').value),basalamFallbackCategoryIds:$('basalamFallbackCategoryIds').value.split(/[,،\s]+/).map(Number).filter(Boolean),networkIndirect:$('networkIndirect').checked,noExtract:$('noExtract').checked,syncWoo:$('syncWoo').checked,syncBasalam:$('syncBasalam').checked}}
async function saveProfile(runAfter=false,stay=false,opts={}){const silent=Boolean(opts.silent),button=runAfter?$('scrapeForm'):stay?$('savePriceSettings'):$('saveBtn');if(!silent)busy(button,true);try{if(stay&&!$('profileId').value){if(silent)return;throw Error('ابتدا یک پروفایل را از بالای صفحه انتخاب کنید.')}if(!$('url').value.trim()&&!$('noExtract').checked){if(silent)return;throw Error('آدرس پروفایل برای حالت استخراج اجباری است.')}const result=await api('/api/profiles',{method:'POST',body:JSON.stringify(profileBody())});rememberProfile(result.profile.id);$('profileId').value=result.profile.id;await refreshProfiles();syncProfileSelects(result.profile.id);if(!silent)notice('پروفایل «'+result.profile.name+'» ذخیره شد.');if(runAfter)await createJob(result.profile.id,'scrape');else if(!stay&&!silent)tab('home')}catch(error){if(silent)return;notice(error.message,'error');output({error:error.message})}finally{if(!silent)busy(button,false)}}
async function refreshProfiles(){const data=await api('/api/profiles');state.profiles=data.profiles;renderProfiles();$('statProfiles').textContent=fa(state.profiles.length)}
async function profileAction(action,id){try{if(action==='edit')return editProfile(id);if(action==='diagnose')return runExtractionDiagnostic(id);if(action==='delete'){if(!confirm('پروفایل و محصولات آن حذف شود؟'))return;const wasActive=state.selected===id||$('profileId').value===id||rememberedProfileId()===id;await api('/api/profiles/'+encodeURIComponent(id),{method:'DELETE'});forgetRememberedProfile(id);await refreshProfiles();if(wasActive)clearForm();notice('پروفایل حذف شد.');return}await createJob(id,action)}catch(error){notice(error.message,'error');output({error:error.message})}}
async function createJob(id,kind,target='both',navigate=true){if(!id)throw Error('ابتدا یک پروفایل انتخاب کنید.');activateProfile(id);const path='/api/profiles/'+encodeURIComponent(id)+'/'+(kind==='sync'?'sync':'scrape'),body={target};const data=await api(path,{method:'POST',body:JSON.stringify(body)});notice(data.processor==='existing-active'?'برای این پروفایل کار استخراج/ارسال فعال وجود دارد؛ کار تکراری ساخته نشد و همان دنبال می‌شود.':'کار تازه ثبت و پردازش آن تحریک شد.','info');output(data);if(navigate)tab('jobs');else await loadJobs(false);watchJob(data.job.id);return data}
function updateDetailSummary(){const filled=detailFields.filter(([id])=>$('sel-'+id).value.trim()).length,gallery=$('galMode').value!=='off'&&Boolean(gallerySelector());$('detailSelectionSummary').textContent=filled||gallery?fa(filled)+' فیلد جزئیات ثبت شده'+(gallery?' · گالری نیز تنظیم شده است.':' · برای ذخیره در پروفایل، دکمهٔ «ذخیره پروفایل» پایین صفحه را بزنید.'):'هنوز سلکتور جزئیاتی ثبت نشده است.'}
async function openVisual(context='list'){const detail=context==='detail',button=$(detail?'openDetailVisual':'openVisual');busy(button,true);try{const url=$(detail?'detailSampleUrl':'url').value.trim();if(!url)throw Error(detail?'ابتدا آدرس نمونهٔ یک محصول را وارد کنید.':'ابتدا آدرس صفحه محصولات را وارد کنید.');const data=await api('/api/visual-ticket',{method:'POST',body:JSON.stringify({url})});$('visualUrl').textContent=(detail?'صفحهٔ جزئیات: ':'صفحهٔ فهرست: ')+url;$('visualModal').classList.add('open');$('visualLoading').hidden=false;$('visualFrame').hidden=true;$('visualFrame').src=U('/visual?context=')+(detail?'detail':'list')+'&ticket='+encodeURIComponent(data.ticket)}catch(error){notice(error.message,'error')}finally{busy(button,false)}}
function closeVisual(){$('visualModal').classList.remove('open');$('visualFrame').src='about:blank'}
function applyVisualSelection(mode,item={}){const selector=String(item.selector||'').trim();if(!selector)return false;if(mode==='gallery'||mode==='galleryOne'){$('galMode').value='manual';$('galSelectors').value=selector;galModeChanged();updateDetailSummary();return true}if(mode==='galleryBox'){$('galMode').value='auto';$('galBox').value=selector;galModeChanged();updateDetailSummary();return true}const input=$('sel-'+mode);if(!input)return false;input.value=selector;$('result-'+mode).textContent=fa(item.count||0)+' مورد · '+(item.preview||'ثبت شد');$('wrap-'+mode).classList.add('has');if(detailFields.some(([id])=>id===mode))updateDetailSummary();return true}
function visualMessage(event){if(event.origin!==location.origin)return;const message=event.data||{};if(message.type==='scraper4-selector'){if(!applyVisualSelection(message.mode,message))return;const detail=['shortDesc','longDesc','sku','category','tags','weight','stock','brand','detailImage','gallery','galleryBox','galleryOne','variations'].includes(message.mode);subTab(detail?'details':'selectors');notice('سلکتور «'+(detailFields.find(([id])=>id===message.mode)?.[1]||message.mode)+'» ثبت شد؛ می‌توانید فیلد بعدی را انتخاب کنید.');return}if(message.type==='scraper4-detail-selectors'){let applied=0;for(const [mode,item] of Object.entries(message.selections||{}))if(applyVisualSelection(mode,item))applied++;subTab('details');closeVisual();notice(fa(applied)+' انتخاب صفحهٔ جزئیات اعمال شد؛ در پایان پروفایل را ذخیره کنید.',applied?'ok':'info')}}
async function suggestSelectorFields(){const button=$('suggestSelectors');busy(button,true);try{const url=$('url').value.trim();if(!url)throw Error('ابتدا آدرس پروفایل را وارد کنید.');const data=await api('/api/suggest-selectors',{method:'POST',body:JSON.stringify({url,mode:'list'})});for(const [id] of listFields){const selector=data.selectors[id];if(!selector)continue;$('sel-'+id).value=selector;const info=data.evidence[id]||{};$('result-'+id).textContent=fa(info.count||0)+' مورد · '+(info.sample||'پیشنهاد شد');$('wrap-'+id).classList.add('has')}output(data);notice(Object.keys(data.selectors).length?'سلکتورهای پیشنهادی ثبت شدند؛ نتیجه را آزمایش کنید.':'پیشنهاد مطمئنی پیدا نشد؛ از انتخاب بصری استفاده کنید.',Object.keys(data.selectors).length?'ok':'info')}catch(error){notice(error.message,'error')}finally{busy(button,false)}}
async function suggestDetailFields(){const button=$('suggestDetails');busy(button,true);try{const url=$('detailSampleUrl').value.trim();if(!url)throw Error('آدرس نمونهٔ یک محصول را وارد کنید.');const data=await api('/api/suggest-selectors',{method:'POST',body:JSON.stringify({url,mode:'detail'})});for(const [id] of detailFields){const selector=data.selectors[id];if(!selector)continue;$('sel-'+id).value=selector;const info=data.evidence[id]||{};$('result-'+id).textContent=fa(info.count||0)+' مورد · '+(info.sample||'پیشنهاد شد');$('wrap-'+id).classList.add('has')}if(data.selectors.gallery){$('galMode').value='manual';$('galSelectors').value=data.selectors.gallery;galModeChanged()}updateDetailSummary();output(data);notice(Object.keys(data.selectors).length?'سلکتورهای جزئیات و تنوع پیشنهاد شدند؛ آن‌ها را بررسی کنید.':'پیشنهاد مطمئنی پیدا نشد؛ از انتخاب بصری استفاده کنید.',Object.keys(data.selectors).length?'ok':'info')}catch(error){notice(error.message,'error')}finally{busy(button,false)}}
function clearDetailSelectors(){for(const [id] of detailFields){$('sel-'+id).value='';$('result-'+id).textContent='—';$('wrap-'+id).classList.remove('has')}loadGallery();updateDetailSummary();notice('سلکتورهای صفحهٔ جزئیات پاک شدند.','info')}
async function testDetailSelectors(){const button=$('testDetails');busy(button,true);try{const url=$('detailSampleUrl').value.trim(),results=[];if(!url)throw Error('ابتدا آدرس نمونهٔ یک محصول را وارد کنید.');for(const [id,label] of detailFields){const selector=$('sel-'+id).value.trim();if(!selector)continue;const type=id==='detailImage'?'image':id==='variations'?'variations':'text';try{const data=await api('/api/test-selector',{method:'POST',body:JSON.stringify({url,selector,type})}),samples=data.values||data.variations||[];$('result-'+id).textContent=fa(data.count||samples.length)+' مورد · '+(samples[0]||'بدون مقدار');$('wrap-'+id).classList.toggle('has',(data.count||samples.length)>0);results.push({field:id,label,selector,ok:(data.count||samples.length)>0,count:data.count||samples.length,samples,variationGroups:data.variationGroups})}catch(error){$('result-'+id).textContent='خطا: '+error.message;results.push({field:id,label,selector,ok:false,error:error.message})}}if(!results.length||results.every(x=>!x.ok)){notice('هیچ سلکتور جزئیاتی جواب نداد؛ پیشنهاد خودکار به‌عنوان آخرین راه اجرا می‌شود…','info');await suggestDetailFields()}
const report={ok:results.length>0&&results.every(x=>x.ok),url,tested:results.length,succeeded:results.filter(x=>x.ok).length,failed:results.filter(x=>!x.ok).length,results,gallery:galleryConfig(),recommendations:results.length?results.some(x=>!x.ok)?['فیلدهای بدون نتیجه را با «انتخاب بصری جزئیات» دوباره انتخاب کنید.']:['فیلدهای جزئیات معتبرند؛ تنظیم گالری را هم جداگانه آزمایش کنید.']:['هنوز سلکتور جزئیاتی ثبت نشده است؛ انتخاب بصری یا پیشنهاد خودکار را اجرا کنید.']};output(report);openResultModal('🧪 گزارش جامع آزمایش جزئیات محصول',report);notice(results.length?'آزمایش سلکتورهای جزئیات تمام شد.':'سلکتوری برای آزمایش ثبت نشده است.',report.ok?'ok':'info')}catch(error){openResultModal('⚠️ خطای آزمایش جزئیات',{ok:false,error:error.message});notice(error.message,'error')}finally{busy(button,false)}}
async function testSelectors(){const button=$('testSelectors');busy(button,true);try{const url=$('url').value.trim(),results=[];if(!url)throw Error('ابتدا آدرس پروفایل را وارد کنید.');for(const [id,label] of listFields){const selector=$('sel-'+id).value.trim();if(!selector)continue;const type=['link','image'].includes(id)?id:'text';try{const data=await api('/api/test-selector',{method:'POST',body:JSON.stringify({url,selector,type})});$('result-'+id).textContent=fa(data.count)+' مورد · '+(data.values[0]||'بدون مقدار');$('wrap-'+id).classList.toggle('has',data.count>0);results.push({field:id,label,selector,ok:data.count>0,count:data.count,samples:data.values})}catch(error){$('result-'+id).textContent='خطا: '+error.message;results.push({field:id,label,selector,ok:false,error:error.message})}}if(!results.length||results.every(x=>!x.ok)){notice('هیچ سلکتوری جواب نداد؛ پیشنهاد خودکار به‌عنوان آخرین راه اجرا می‌شود…','info');await suggestSelectorFields()}
const report={ok:results.every(x=>x.ok),url,tested:results.length,succeeded:results.filter(x=>x.ok).length,failed:results.filter(x=>!x.ok).length,results,recommendations:results.some(x=>!x.ok)?['سلکتورهای بدون نتیجه را با انتخاب‌گر بصری دوباره انتخاب کنید.']:['سلکتورهای فهرست معتبر به نظر می‌رسند؛ یک استخراج آزمایشی اجرا کنید.']};output(report);openResultModal('🧪 گزارش جامع آزمایش سلکتورها',report);notice('آزمایش سلکتورها تمام شد.',report.ok?'ok':'error')}catch(error){openResultModal('⚠️ خطای آزمایش سلکتورها',{ok:false,error:error.message});notice(error.message,'error')}finally{busy(button,false)}}
async function testGallery(){const button=$('testGallery');busy(button,true);try{const url=$('detailSampleUrl').value.trim();if(!url)throw Error('آدرس نمونهٔ یک محصول را وارد کنید.');const cfg=galleryConfig(),selector=gallerySelector(cfg);if(!selector)throw Error('تنظیمات روش گالری کامل نیست.');const data=await api('/api/test-selector',{method:'POST',body:JSON.stringify({url,selector,type:'gallery',max:cfg.max,skipFirst:cfg.skip_first})}),report={...data,url,configuration:cfg,selector,recommendations:data.count?['تصاویر پیدا شدند؛ آدرس‌ها را در بخش پاسخ خام بازبینی کنید.']:['سلکتور گالری را با ابزار انتخاب بصری دوباره انتخاب کنید.','بررسی کنید تصاویر پس از اجرای JavaScript ساخته نشده باشند.']};output(report);openResultModal('🖼 گزارش جامع آزمایش گالری',report);notice(data.count?fa(data.count)+' عکس گالری پیدا شد.':'عکسی با تنظیمات گالری پیدا نشد.',data.count?'ok':'info')}catch(error){openResultModal('⚠️ خطای آزمایش گالری',{ok:false,error:error.message});notice(error.message,'error')}finally{busy(button,false)}}
const dest={target:'woo',page:1,totalPages:1,total:0,status:'all',products:[],counts:{},shops:[],selected:new Map(),view:'cards'};
let categoryManager=null,categoryAllTimer=0,categoryAllPollToken=0,categoryAllVisible=false;
let dedupTimer=0,dedupPollToken=0,dedupLastStatus='';
const dedupPhaseLabel=phase=>({listing:'📥 دریافت فهرست محصولات مقصد',grouping:'🧮 گروه‌بندی محصولات همنام',removing:'🗑 حذف تکراری‌ها روی مقصد',finished:'✅ پایان یافت',paused:'⏸ متوقف (قابل ادامه)',failed:'❌ خطا',waiting:'⏳ در صف سرور',recovered:'🔁 بازیابی خودکار',retrying:'🔁 تلاش دوباره'}[phase]||phase||'—');
function dedupTargetLabel(target){return target==='basalam'?'🏪 باسلام':'🛒 ووکامرس'}
function renderDedupRun(run){const el=$('dedupProgress');if(!el)return;if(!run){el.textContent='هنوز اجرایی ثبت نشده است.';return}
 const keepLabel={newest:'جدیدتر می‌ماند، قدیمی‌ترها حذف',oldest:'قدیمی‌تر می‌ماند، جدیدترها حذف',cheapest:'ارزان‌تر می‌ماند، گران‌ترها حذف',expensive:'گران‌تر می‌ماند، ارزان‌ترها حذف'}[run.keep]||run.keep;
 const lines=['مقصد: '+dedupTargetLabel(run.target)+(run.apply?' — حالت حذف واقعی':' — حالت پیش‌نمایش (بدون تغییر روی مقصد)'),'وضعیت: '+dedupPhaseLabel(run.phase)+' ['+run.status+']','معیار نگهداری: '+keepLabel,'فرمت پسوند کد: '+(Array.isArray(run.suffixFormats)?run.suffixFormats.join(' ، '):'—'),'صفحهٔ فهرست: '+fa(run.page||1)+' از '+fa(run.totalPages||1)+' — محصولات بررسی‌شده: '+fa(run.scanned||0),'گروه‌های همنام: '+fa(run.groupsFound||0)+' — نسخه‌های تکراری: '+fa(run.duplicates||0),'حذف‌شده: '+fa(run.removed||0)+' — ناموفق: '+fa(run.failed||0),run.error?('خطای آخر: '+run.error):''].filter(Boolean);
 el.textContent=lines.join('\n');
}
function dedupSummary(run){const groups=(Array.isArray(run.groups)?run.groups:[]).map(group=>({title:group.title,count:group.count,keep:group.keep?{id:group.keep.id,name:group.keep.name,price:group.keep.price,shopId:group.keep.shopId,date:group.keep.date||''}:null,remove:(group.remove||[]).map(item=>({id:item.id,name:item.name,price:item.price,shopId:item.shopId,date:item.date||''}))}));
 return{ok:run.status!=='failed',target:run.target,apply:run.apply,keep:run.keep,suffixFormats:run.suffixFormats,scanned:run.scanned||0,groupsFound:run.groupsFound||0,duplicates:run.duplicates||0,removed:run.removed||0,failedCount:run.failed||0,summary:run.apply?(fa(run.removed||0)+' نسخهٔ تکراری واقعاً حذف شد و '+fa(run.failed||0)+' مورد ناموفق بود. حذف ووکامرس در زباله‌دان و حذف باسلام در بایگانی ۴۱۸۴ برگشت‌پذیر است.'):(fa(run.duplicates||0)+' نسخهٔ تکراری در '+fa(run.groupsFound||0)+' گروه همنام پیدا شد؛ هیچ چیزی حذف نشده است. برای حذف واقعی دکمهٔ قرمز را بزنید.'),groups,log:run.items||[],error:run.error||null};
}
async function refreshDedupRun(showModal){const token=++dedupPollToken;clearTimeout(dedupTimer);try{
 const target=($('dedupTarget')&&$('dedupTarget').value)||'woo',data=await api('/api/destination/'+target+'/dedup-runs/current'),run=data.run;
 if(token!==dedupPollToken)return run;
 renderDedupRun(run);
 if(run&&['queued','running'].includes(run.status)){dedupLastStatus=run.status;dedupTimer=setTimeout(function(){refreshDedupRun(false)},2000);if(showModal)notice('اجرا هنوز در جریان است؛ پیشرفت زنده در همین بخش دیده می‌شود.','info');return run}
 if(run&&run.status==='done'&&(showModal||dedupLastStatus==='running'||dedupLastStatus==='queued')){openResultModal('🧬 نتیجهٔ حذف تکراری‌های '+dedupTargetLabel(run.target),dedupSummary(run));notice(run.apply?fa(run.removed||0)+' نسخهٔ تکراری حذف شد.':fa(run.duplicates||0)+' نسخهٔ تکراری شناسایی شد.','ok')}
 else if(run&&showModal)openResultModal('🧬 وضعیت اجرای حذف تکراری‌ها',dedupSummary(run));
 else if(!run&&showModal)notice('اجرایی برای نمایش نیست؛ ابتدا پیش‌نمایش یا حذف سرورساید را شروع کنید.','info');
 if(run)dedupLastStatus=run.status;
 return run;
}catch(error){notice(error.message,'error')}}
async function handleDedupAction(action){
 const target=($('dedupTarget')&&$('dedupTarget').value)||'woo';
 if(action==='status')return openDedupLiveModal();
 if(action==='stop'||action==='resume'){const data=await api('/api/destination/'+target+'/dedup-runs/control',{method:'POST',body:JSON.stringify({action})});renderDedupRun(data.run);notice(action==='stop'?'توقف امن در checkpoint سرور ثبت شد.':'اجرا از همان checkpoint سرور ادامه یافت.','info');return refreshDedupRun(false)}
 if(action==='reset'){await api('/api/destination/'+target+'/dedup-runs/reset',{method:'POST',body:'{}'});dedupLastStatus='';const el=$('dedupProgress');if(el)el.textContent='اجرای قبلی پاک شد.';return notice('اجرای حذف تکراری پاک شد و می‌توانید اجرای تازه شروع کنید.','info')}
 const apply=action==='apply';
 if(apply&&!confirm('حذف واقعی تکراری‌ها روی '+dedupTargetLabel(target)+' اجرا شود؟ نسخه‌های اضافی ووکامرس به زباله‌دان و باسلام به بایگانی ۴۱۸۴ می‌روند (برگشت‌پذیر).'))return;
 await saveSettings();
 const body={keep:($('dedupKeep')&&$('dedupKeep').value)||'newest',suffixFormats:($('dedupSuffix')&&$('dedupSuffix').value)||'',apply};
 const data=await api('/api/destination/'+target+'/dedup-runs',{method:'POST',body:JSON.stringify(body)});
 dedupLastStatus='queued';renderDedupRun(data.run);
 notice(data.existing?'اجرای قبلی هنوز فعال است و همان ادامه می‌یابد؛ برای شروع تازه ابتدا «پاک‌کردن اجرا» را بزنید.':'اجرای سرورساید آغاز شد؛ حتی با بستن صفحه ادامه می‌یابد و خطای شبکه نمی‌گیرد.','info');
 return openDedupLiveModal();
}
let dedupLiveTimer=0;
function openDedupLiveModal(){const target=($('dedupTarget')&&$('dedupTarget').value)||'woo';modalShell('🧬 اجرای زندهٔ حذف تکراری‌ها — '+dedupTargetLabel(target),'<div id="dedupLiveBody"><div class="empty">در حال دریافت وضعیت از سرور…</div></div>');dedupLivePoll()}
async function dedupLivePoll(){clearTimeout(dedupLiveTimer);if(!document.getElementById('resultModal'))return;try{
  const target=($('dedupTarget')&&$('dedupTarget').value)||'woo',data=await api('/api/destination/'+target+'/dedup-runs/current'),run=data.run,body=$('dedupLiveBody');
  if(!body)return;
  if(!run){body.innerHTML='<div class="empty">هنوز اجرایی ثبت نشده است.</div>';return}
  const running=['queued','running'].includes(run.status),progress=run.totalPages?Math.round(((run.page||1)/run.totalPages)*100):0;
  const items=(run.items||[]).slice(-40).map(item=>'<div style="border-bottom:1px solid #1e293b;padding:5px 0;font-size:10px"><span class="chip" style="background:'+(item.ok?'#14532d':'#7f1d1d')+';color:'+(item.ok?'#86efac':'#fca5a5')+'">'+(item.ok?'✓':'✗')+'</span> '+(item.shopId&&item.shopId!=='default'?'<span class="chip">'+esc(item.shopId)+'</span>':'')+' '+esc(item.name||'')+(item.action?' — '+esc(item.action):'')+(item.error?' <span style="color:#fca5a5">'+esc(item.error)+'</span>':'')+'</div>').join('');
  body.innerHTML='<div class="detail-grid">'+[['وضعیت',dedupPhaseLabel(run.phase)+' ['+run.status+']'],['معیار نگهداشت',({newest:'جدیدتر بماند',oldest:'قدیمی‌تر بماند',cheapest:'ارزان‌تر بماند',expensive:'گران‌تر بماند'}[run.keep]||run.keep)],['فرمت پسوند',(run.suffixFormats||[]).join(' ، ')||'—'],['بررسی‌شده',fa(run.scanned||0)],['گروه همنام',fa(run.groupsFound||0)],['تکراری',fa(run.duplicates||0)],['حذف‌شده',fa(run.removed||0)],['ناموفق',fa(run.failed||0)]].map(item=>'<div class="detail-item"><small>'+esc(item[0])+'</small><span>'+esc(item[1]||'—')+'</span></div>').join('')+'</div>'+(running?'<div class="progress"><div class="bar" style="width:'+progress+'%"></div></div><div style="font-size:10px;color:#94a3b8;margin-bottom:6px">صفحهٔ '+fa(run.page||1)+' از '+fa(run.totalPages||1)+' — هر ۲ ثانیه به‌روزرسانی خودکار (با بستن صفحهٔ مرورگر ادامه می‌یابد)</div>':'')+(run.error?'<div class="result-summary bad"><b>✗ خطا</b><br>'+esc(run.error)+'</div>':'')+'<h3>🧾 لاگ زنده ('+fa((run.items||[]).length)+' مورد)</h3><div style="max-height:34vh;overflow:auto;padding:8px;background:#020617;border:1px solid #1e293b;border-radius:8px">'+(items||'<div class="empty">هنوز موردی ثبت نشده است.</div>')+'</div>';
  if(running){dedupLiveTimer=setTimeout(dedupLivePoll,2000);if(dedupLastStatus!==run.status)dedupLastStatus=run.status}else{dedupLastStatus=run.status}
}catch(error){const body=$('dedupLiveBody');if(body)body.innerHTML='<div class="result-summary bad"><b>✗ خطا در دریافت وضعیت</b><br>'+esc(error.message)+'</div>'}}
function categoryRunStatus(run){return{queued:'در صف سرور',running:run.phase==='listing'?'در حال دریافت همهٔ صفحات تأییدنشده':'در حال دسته‌بندی سرورساید',paused:'متوقف‌شده؛ قابل ادامه',done:'کامل شد',failed:'ناموفق؛ قابل تلاش دوباره'}[run?.status]||'نامشخص'}
function renderCategoryAllRun(run){if(!run||!categoryAllVisible)return;const total=Number(run.total||0),processed=Number(run.processed||0),percent=total?Math.min(100,Math.round(processed/total*100)):0,items=Array.isArray(run.items)?run.items:[],rows=items.slice(-100).reverse().map(item=>'<tr><td>#'+fa(item.id)+'</td><td>'+esc(item.title||'—')+'</td><td>'+esc(item.shopId||'—')+'</td><td>'+(item.ok?'✓ '+esc(item.categoryName||'')+' (#'+fa(item.categoryId)+')':'<span style="color:#fca5a5">'+esc(item.error||'ناموفق')+'</span>')+'</td></tr>').join(''),active=['queued','running'].includes(run.status),canResume=['paused','failed'].includes(run.status),phase=run.phase==='listing'?'صفحه '+fa(run.page)+' از '+fa(run.totalPages)+' فهرست مقصد':'محصول '+fa(processed)+' از '+fa(total),summaryClass=run.status==='failed'?'bad':'ok';modalShell('🏷 دسته‌بندی همهٔ محصولات تأییدنشدهٔ باسلام','<div class="result-summary '+summaryClass+'"><b>'+esc(categoryRunStatus(run))+'</b><br>'+esc(phase)+(run.error?'<br>خطا: '+esc(run.error):'')+'<br><small>این عملیات روی سرور ذخیره شده است؛ refresh یا بستن صفحه آن را متوقف نمی‌کند.</small></div><div class="ai-progress-track"><i style="width:'+percent+'%"></i></div><div class="ai-progress-stats"><div class="ai-progress-stat">کل شناسایی‌شده<b>'+fa(total)+'</b></div><div class="ai-progress-stat">پردازش‌شده<b>'+fa(processed)+'</b></div><div class="ai-progress-stat">تغییریافته<b>'+fa(run.changed)+'</b></div><div class="ai-progress-stat">ناموفق<b>'+fa(run.failed)+'</b></div></div><div class="bulk-actions">'+(active?'<button class="btn btn-red" data-category-run="stop">■ توقف امن</button>':'')+(canResume?'<button class="btn btn-green" data-category-run="resume">↻ ادامه از checkpoint</button>':'')+'<button class="btn btn-gray" data-category-run="refresh">↻ تازه‌سازی</button></div><h3 style="margin-top:14px">نتایج اخیر ذخیره‌شده</h3><p class="field-hint">تا ۳۰۰ نتیجهٔ اخیر نگهداری می‌شود؛ شمارنده‌های بالا نتیجهٔ کامل همهٔ محصولات را نشان می‌دهند.</p><div style="overflow:auto"><table class="result-table"><thead><tr><th>شناسه</th><th>محصول</th><th>غرفه</th><th>نتیجه</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+(rows?'':'<div class="empty compact">هنوز محصولی پردازش نشده است.</div>'));const root=$('resultModal'),baseClick=root.onclick;root.onclick=event=>{if(event.target===root||event.target.closest('[data-modal-action="close"]')){categoryAllVisible=false;clearTimeout(categoryAllTimer);return root.remove()}const action=event.target.closest('[data-category-run]')?.dataset.categoryRun;if(action){controlCategoryAllRun(action).catch(error=>openResultModal('⚠️ خطای کنترل اجرای دسته‌بندی',{ok:false,error:error.message}));return}baseClick(event)}}
async function refreshCurrentCategoryRun(presentActive=false){const token=++categoryAllPollToken;clearTimeout(categoryAllTimer);try{const data=await api('/api/destination/basalam/category-runs/current'),run=data.run;if(token!==categoryAllPollToken)return run;if(run&&presentActive&&['queued','running'].includes(run.status))categoryAllVisible=true;if(run&&categoryAllVisible)renderCategoryAllRun(run);if(run&&['queued','running'].includes(run.status))categoryAllTimer=setTimeout(()=>refreshCurrentCategoryRun(false),2000);return run}catch(error){if(categoryAllVisible)categoryAllTimer=setTimeout(()=>refreshCurrentCategoryRun(false),5000);return null}}
async function controlCategoryAllRun(action){if(action==='refresh')return refreshCurrentCategoryRun(false);const data=await api('/api/destination/basalam/category-runs/control',{method:'POST',body:JSON.stringify({action})});categoryAllVisible=true;renderCategoryAllRun(data.run);notice(action==='stop'?'توقف امن در checkpoint سرور ثبت شد.':'دسته‌بندی همهٔ تأییدنشده‌ها از checkpoint ادامه یافت.','info');return refreshCurrentCategoryRun(false)}
async function startCategoryAllRun(){if(!confirm('همهٔ محصولات «تأیید نشده» در تمام صفحات و تمام غرفه‌های باسلام با مدل‌های موفق دسته‌بندی و تغییر واقعی داده شوند؟'))return;categoryAllVisible=true;modalShell('🏷 آماده‌سازی دسته‌بندی همهٔ تأییدنشده‌ها','<div class="dest-loading">در حال بررسی اتصال، دسته‌ها و مدل‌های موفق…</div>');try{const data=await api('/api/destination/basalam/category-runs',{method:'POST',body:'{}'});renderCategoryAllRun(data.run);notice(data.existing?'اجرای قبلی هنوز فعال است و همان progress بازیابی شد.':'اجرای سرورساید همهٔ محصولات تأییدنشده آغاز شد.','info');return refreshCurrentCategoryRun(false)}catch(error){categoryAllVisible=false;openResultModal('⚠️ شروع دسته‌بندی همهٔ تأییدنشده‌ها',{ok:false,error:error.message,recommendations:['ابتدا تست سرورساید مدل‌ها را کامل کنید تا حداقل یک مدل موفق ثبت شود.','توکن و دسته‌های باسلام را از بخش اتصال آزمایش کنید.']})}}
