  // Columns = destinations, rows = products. One cell per (product, destination).
  const accounts=[],seen=new Set();
  for(const row of d.rows){const key=row.target+':'+row.accountKey;if(seen.has(key))continue;seen.add(key);accounts.push({key,name:row.accountName,target:row.target});}
  const products=new Map();
  for(const row of d.rows){
    const id=row.bucket==='extra'?('x:'+row.accountKey+':'+(row.remoteId||row.remoteTitle)):(row.profileId+'|'+row.sourceKey);
    if(!products.has(id))products.set(id,{title:row.title||row.remoteTitle,profileName:row.profileName||'',sourcePrice:row.sourcePrice,duplicateCount:row.duplicateCount||0,cells:{},worst:5});
    const entry=products.get(id);
    entry.cells[row.target+':'+row.accountKey]=row;
    const rank={unreachable:0,priceDiff:1,missing:2,extra:3,noPrice:4,matched:5}[row.bucket];
    if(rank<entry.worst)entry.worst=rank;
    if(entry.sourcePrice===null||entry.sourcePrice===undefined)entry.sourcePrice=row.sourcePrice;
    if(!entry.duplicateCount&&row.duplicateCount)entry.duplicateCount=row.duplicateCount;
  }
  const list=[...products.values()].sort((a,b)=>(a.worst-b.worst)||String(a.title).localeCompare(String(b.title),'fa'));
  const shown=options.limit?list.slice(0,options.limit):list;
  const money=v=>v===null||v===undefined?'—':Number(v).toLocaleString('fa-IR');
  const head='<thead><tr>'
    +'<th class="rc-sticky rc-th">محصول</th><th class="rc-th rc-profile">پروفایل</th><th class="rc-th rc-num">قیمت مبدأ</th><th class="rc-th rc-num rc-dup" title="تعداد محصولاتی که با نادیده‌گرفتن پسوند کد، عنوان یکسان دارند">تکراری</th>'
    +accounts.map(a=>'<th class="rc-th rc-dest">'+(a.target==='woo'?'🛒':'🏪')+' '+esc(a.name)+'</th>').join('')
    +'</tr></thead>';
  const body='<tbody>'+shown.map(p=>'<tr>'
    +'<td class="rc-sticky rc-title" title="'+esc(p.title)+'">'+esc(p.title)+'</td>'
    +'<td class="rc-profile">'+esc(p.profileName||'—')+'</td>'
    +'<td class="rc-num">'+money(p.sourcePrice)+'</td>'
    +'<td class="rc-num rc-dup"'+(p.duplicateCount>1?' style="color:#fbbf24;font-weight:700"':'')+'>'+(p.duplicateCount?fa(p.duplicateCount):'—')+'</td>'
    +accounts.map(a=>reconMatrixCell(p.cells[a.key])).join('')+'</tr>').join('')+'</tbody>';
  const more=list.length>shown.length?'<div class="rc-more">… و '+fa(list.length-shown.length)+' محصول دیگر. برای فهرست کامل خروجی JSON را ببینید.</div>':'';
  const legend='<div class="rc-legend">'
    +[['matched','هماهنگ'],['priceDiff','اختلاف قیمت'],['missing','در مقصد نیست'],['extra','فقط در مقصد'],['noPrice','بدون قیمت مبدأ'],['none','ارسال نمی‌شود']]
      .map(([b,label])=>{const [color,bg]=reconCellStyle(b);return '<span class="rc-chip" style="color:'+color+';background:'+bg+';border-color:'+color+'55">'+esc(label)+'</span>'}).join('')
    +'</div>';
  const counts='<div class="rc-counts">'
    +[['matched','هماهنگ',d.matched],['priceDiff','اختلاف قیمت',d.priceDiff],['missing','در مقصد نیست',d.missing],['extra','فقط در مقصد',d.extra],['noPrice','بدون قیمت',d.noPrice]]
      .map(([b,label,n])=>{const [color,bg]=reconCellStyle(b);return '<span class="rc-count" style="color:'+color+';background:'+bg+';border-color:'+color+'55"><b>'+fa(n||0)+'</b> '+esc(label)+'</span>'}).join('')
    +'<span class="rc-count rc-muted"><b>'+fa(list.length)+'</b> محصول · <b>'+fa(accounts.length)+'</b> مقصد</span>'+(d.skippedNoCode?'<span class="rc-count rc-muted" title="فقط محصولات دارای پسوند (کد ایکس) مقایسه و هماهنگ می‌شوند"><b>'+fa(d.skippedNoCode)+'</b> بدون پسوند کد (نادیده گرفته شد)</span>':'')+'</div>';
  const fails=(d.failures||[]).map(f=>'<div class="rc-fail">⚠️ '+esc(f.account)+': '+esc(f.error)+'</div>').join('');
  const planned=Number(d.planned||0);
  const anyFailed=(d.failures||[]).length>0;
  const banner=d.inSync&&!anyFailed
