    +'<td style="padding:4px 6px;font-size:10px;color:#94a3b8;white-space:nowrap">'+esc(r.profileName||'—')+'</td>'
    +'<td style="padding:4px 6px">'+esc(r.title||r.remoteTitle)+'</td>'
    +'<td style="padding:4px 6px;text-align:left;white-space:nowrap">'+reconMoney(r.sourcePrice)+'</td>'
    +'<td style="padding:4px 6px;text-align:left;white-space:nowrap;color:#93c5fd">'+reconMoney(r.expectedPrice)+'</td>'
    +'<td style="padding:4px 6px;text-align:left;white-space:nowrap">'+reconMoney(r.remotePrice)+'</td>'
    +'<td style="padding:4px 6px;text-align:left;white-space:nowrap;color:'+(r.delta?'#fbbf24':'#64748b')+'">'+(r.delta?(r.delta>0?'+':'')+Number(r.delta).toLocaleString('fa-IR'):'—')+'</td>'
