  const th=(t,align)=>'<th style="padding:5px 6px;text-align:'+(align||'right')+'">'+t+'</th>';
  return '<div style="margin-bottom:6px">'+chips
    +'<span style="font-size:11px;color:#94a3b8;margin-right:6px">مبدأ '+fa(d.local||0)+' · مقصدها '+fa(d.accounts||0)+' · اقدام قابل اجرا '+fa(d.actions||0)+'</span></div>'
    +fails
    +(accounts?'<div style="font-size:11px;color:#93c5fd;margin:6px 0 2px">هر مقصد</div><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="color:#93c5fd">'+th('مقصد')+th('یکسان','center')+th('قیمت','center')+th('نبود','center')+th('اضافی','center')+th('وضعیت','center')+'</tr></thead><tbody>'+accounts+'</tbody></table>':'')
