  if(action==='prompt-new'){['agentPromptId','agentPromptName','agentPromptDesc','agentPromptBody','agentPromptModelKey'].forEach(id=>{const el=$(id);if(el)el.value=''});$('agentPromptSchedule').value='0';$('agentPromptMaxSteps').value='6';$('agentPromptEnabled').checked=true;return notice('فرم پرامپت تازه شد؛ پس از نوشتن، ذخیره کنید.','info')}
  if(action.startsWith('prompt-edit:')){const id=action.slice(12),p=agentData.prompts.find(x=>x.id===id);if(!p)return;['agentPromptId','agentPromptName','agentPromptDesc','agentPromptBody','agentPromptModelKey'].forEach(key=>{const el=$(key);if(el)el.value=''});$('agentPromptId').value=p.id;$('agentPromptName').value=p.name;$('agentPromptDesc').value=p.description||'';$('agentPromptBody').value=p.prompt;$('agentPromptModelKey').value=p.modelKey||'';$('agentPromptSchedule').value=String(p.scheduleMinutes||0);$('agentPromptMaxSteps').value=String(p.maxSteps||6);$('agentPromptEnabled').checked=p.enabled!==false;agentToolsChecks('agentPromptTools',agentData.tools,p.tools);return notice('پرامپت در فرم بارگذاری شد؛ پس از ویرایش ذخیره کنید.','info')}
  if(action.startsWith('prompt-run:')){const id=action.slice(11);await api('/api/agent/prompts/'+encodeURIComponent(id)+'/run',{method:'POST',body:'{}'});agentAutoOpenOnDone=true;notice('پرامپت در صف سرور قرار گرفت.','info');return refreshAgentStatus()}
  if(action.startsWith('prompt-delete:')){const id=action.slice(14);if(!confirm('پرامپت و تمام لاگ‌هایش حذف شود؟'))return;await api('/api/agent/prompts/'+encodeURIComponent(id),{method:'DELETE'});return loadAgentTab()}
  if(action.startsWith('prompt-logs:')){const id=action.slice(12),data=await api('/api/agent/runs'),runs=(data.items||[]).filter(r=>r.promptId===id).slice(0,12);if(!runs.length)return notice('اجرایی برای این پرامپت ثبت نشده است.','info');const merged=[].concat(...runs.map(r=>r.logs||[])).reverse();openAgentLogs('اجراهای «'+(agentData.prompts.find(p=>p.id===id)?.name||'')+'»',{...runs[0],logs:merged});return null}
  if(action==='runs-refresh')return loadAgentTab();
  if(action.startsWith('run-logs:')){const id=action.slice(9),data=await api('/api/agent/runs/'+encodeURIComponent(id));if(!data.run)return notice('اجرا پیدا نشد.','error');return openAgentLogs(data.run.name||'اجرای ایجنتیک',data.run)}
  if(action.startsWith('run-delete:')){const id=action.slice(11);if(!confirm('لاگ اجرا حذف شود؟'))return;await api('/api/agent/runs/'+encodeURIComponent(id),{method:'DELETE'});return loadAgentTab()}
